window.__HRC_SHARD({"shard":"ohchr-obe-belarus","builtAt":"2026-10-23T22:07:26+00:00","documents":[{"rec_id":"recAPuPpgVIcezr4x","doc_id":"OHCHR OBE Belarus - Official report - 04.03.2022","symbol":"A/HRC/49/71","title":"Report of the OHCHR Office of the High Commissioner - Examination on Belarus","type":"Official report","date":"2022-03-04","year":2022,"bodies":["OHCHR OBE Belarus"],"paragraphCount":111,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/OHCHR OBE Belarus - 04-03-2022 - Official report - A_HRC_49_71 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recQ5W70vZA26WyLA","doc_id":"OHCHR OBE Belarus - Official report - 03.02.2023","symbol":"A/HRC/52/68","title":"Situation of human rights in Belarus in the run-up to the 2020 presidential election and in its aftermath","type":"Official report","date":"2023-02-03","year":2023,"bodies":["OHCHR OBE Belarus"],"paragraphCount":105,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/OHCHR OBE Belarus - 03-02-2023 - Official report - A_HRC_52_68 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recBsBtAmsSlwegkE","doc_id":"OHCHR OBE Belarus - Official report - 25.03.2024","symbol":"A/HRC/55/61","title":"Report on the Situation of Human Rights in Belarus - OHCHR Examination","type":"Official report","date":"2024-03-25","year":2024,"bodies":["OHCHR OBE Belarus"],"paragraphCount":109,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/OHCHR OBE Belarus - 25-03-2024 - Official report - A_HRC_55_61 - EN.md","extractor":"pdftotext -layout"}],"paragraphs":[{"id":"a-hrc-49-71-u0000","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":null,"seq":0,"section":null,"text":"United Nations                                                                                   A/HRC/49/71\nGeneral Assembly                                                           Distr.: General\n4 March 2022","unnumbered":true},{"id":"a-hrc-49-71-u0001","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":null,"seq":1,"section":null,"text":"Summary\nIn the present report, the United Nations High Commissioner for Human Rights\nprovides an overview of the situation of human rights in Belarus with respect to the 9 August\n2020 election, including the infliction of arbitrary detentions, torture and other cruel,\ninhuman or degrading treatment, failure to effectively investigate allegations of such\nviolations and lack of respect for due process and fair trial rights.\nThe High Commissioner includes updates on critical developments and incidents on\nwhich her examination has collected, consolidated, preserved and analysed information and\nevidence with a view to contributing to accountability for perpetrators and justice for victims.","unnumbered":true},{"id":"a-hrc-49-71-p0001","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"1","seq":2,"section":"I. Introduction","text":"In its resolution 46/20, the Human Rights Council requested the United Nations High\nCommissioner for Human Rights to monitor and report on the situation of human rights in\nBelarus in the run-up to the 2020 presidential election and in its aftermath, and to carry out a\ncomprehensive examination of all alleged human rights violations committed in Belarus\nsince 1 May 2020. The Council also requested the High Commissioner to present an interim\noral update at its forty-eighth session and a comprehensive written report at its forty-ninth\nsession."},{"id":"a-hrc-49-71-p0002","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"2","seq":3,"section":"I. Introduction","text":"In accordance with that mandate, the High Commissioner established an examination\nteam on the situation of human rights in Belarus with a secretariat based in Geneva. On 19\nMay 2021, the High Commissioner appointed three experts to assist her in the discharge of\nthe present mandate: Karinna Moskalenko (Russian Federation), Susan Bazilli (Canada) and\nMarko Milanović (Serbia)."},{"id":"a-hrc-49-71-p0003","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"3","seq":4,"section":"II. Methodology and standard of proof","text":"Pursuant to resolution 46/20, the Office of the United Nations High Commissioner for\nHuman Rights (OHCHR) interpreted the mandate to cover the period from 1 May 2020 to 31\nDecember 2021."},{"id":"a-hrc-49-71-p0004","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"4","seq":5,"section":"II. Methodology and standard of proof","text":"On 8 November 2021, OHCHR formally requested access to the territory of Belarus\nto facilitate its discharge of the examination. OHCHR regrets the unwillingness of the\nGovernment of Belarus to recognize or engage with its examination, and its refusal to allow\naccess to its territory, despite the fact that the Human Rights Council expressly called upon\nit to do so."},{"id":"a-hrc-49-71-p0005","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"5","seq":6,"section":"II. Methodology and standard of proof","text":"The present report is primarily based on information received during 145 first-hand\ninterviews (with 95 men, 49 women and one male child), conducted both in-person and\nremotely. A wide range of victims, witnesses, lawyers, non-governmental organizations and\nother stakeholders were met in person or communicated with via remote means. During the\nconduct of the examination, OHCHR exercised due diligence in assessing the credibility and\nreliability of all sources and cross-checked the information gathered to verify its validity,\nsought informed consent from the sources it interviewed and took all appropriate measures\nto protect confidentiality."},{"id":"a-hrc-49-71-p0006","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"6","seq":7,"section":"II. Methodology and standard of proof","text":"In response to a public call,1 OHCHR received 170 individual submissions. It also\nreceived material from other sources with inside knowledge of and access to internal records\nof Belarusian security forces. OHCHR was able to verify the authenticity of these materials\nand found them to be credible.2"},{"id":"a-hrc-49-71-p0007","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"7","seq":8,"section":"II. Methodology and standard of proof","text":"The methodology employed during the examination was based on international\nstandards and best practices on human rights investigations set out by OHCHR,3 which also\ndeveloped its work to collect, preserve and analyse information, preparing a basis for longer-\nterm collection and verification efforts. In addition to first-hand statements, it collected,\nconsolidated, preserved and analysed more than 400 items of information and evidence,\nincluding photographs, videos, public statements by officials, copies of original medical\nrecords, court documents and other digital data."},{"id":"a-hrc-49-71-p0008","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"8","seq":9,"section":"II. Methodology and standard of proof","text":"Violations were recorded in all six oblasts (administrative regions) of Belarus, though\npredominantly in Minsk."},{"id":"a-hrc-49-71-p0009","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"9","seq":10,"section":"II. Methodology and standard of proof","text":"OHCHR used “reasonable grounds to believe” as the standard of proof. This standard\nis met when factual information has been collected that would satisfy an objective and\nordinarily prudent observer that the incident has occurred as described with a reasonable\ndegree of certainty. This standard of proof is lower than that required for finding criminal\nresponsibility."},{"id":"a-hrc-49-71-p0010","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"10","seq":11,"section":"II. Methodology and standard of proof","text":"OHCHR extends its gratitude to Member States, the Special Rapporteur on the\nsituation of human rights in Belarus, civil society organizations, including the International\nAccountability Platform for Belarus, the experts and, in particular, those who experienced or\nwitnessed human rights violations and were willing to share their personal accounts."},{"id":"a-hrc-49-71-p0011","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"11","seq":12,"section":"III. Applicable law","text":"The facts documented by OHCHR during its examination were assessed in the light\nof applicable international law. It also took into account human rights guarantees under the\nConstitution of Belarus and other domestic law."},{"id":"a-hrc-49-71-p0012","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"12","seq":13,"section":"III. Applicable law","text":"Belarus is a State party to core United Nations human rights treaties,4 and is therefore\nbound by the obligations contained therein."},{"id":"a-hrc-49-71-p0013","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"13","seq":14,"section":"III. Applicable law","text":"During the examination, OHCHR assessed incidents involving the use of force by law\nenforcement officials by reference to applicable international norms and standards,5\nincluding the Code of Conduct for Law Enforcement Officials and the Basic Principles on\nthe Use of Force and Firearms by Law Enforcement Officials (see paras. 22–34 below).\nRequirements of necessity and proportionality set limits on when and how force may be used\nlawfully during any policing actions. The use of force must also pursue a legitimate aim and\nbe provided for by law."},{"id":"a-hrc-49-71-p0014","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"14","seq":15,"section":"III. Applicable law","text":"States have the duty to respect, protect and fulfil human rights, and are responsible for\nany human rights violations committed by their organs or agents. 6 Inherent in these duties is\nthe obligation to prevent the perpetration of violations and to ensure that victims have\naccessible and effective remedies (see paras. 87–92 below).7"},{"id":"a-hrc-49-71-p0015","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"15","seq":16,"section":"III. Applicable law","text":"States also have a duty to investigate and prosecute gross violations of international\nhuman rights law. Investigations into such allegations must be carried out by independent\nand impartial bodies and be prompt, thorough and effective (see paras. 54–57 below).8"},{"id":"a-hrc-49-71-p0016","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"16","seq":17,"section":"IV. Pre-election period (1 May to 8 August 2020)","text":"Following the decision of the incumbent President, Alexander Lukashenko, to seek a\nfurther term in office, the situation of human rights in Belarus markedly deteriorated. Though\nopposition candidates Viktor Babaryko and Valery Tsepkalo submitted the required number\nof signatures to stand in the elections, the Central Election Commission refused to register\nthem (A/HRC/46/4, para. 15)."},{"id":"a-hrc-49-71-p0017","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"17","seq":18,"section":"IV. Pre-election period (1 May to 8 August 2020)","text":"A number of opposition candidates were detained arbitrarily ahead of the election.\nBlogger Sergey Tikhanovsky and activist Vladimir Navumik were arrested in Grodno on\n29 May while collecting signatures for an opposing candidature. Viktor Babaryko and his\nson were detained on 18 June. Women involved in opposition politics and the female relatives\nof political activists were particularly targeted by reprisals. Vitalia Navumik was threatened\nwith the removal of her children, as was Svetlana Tikhanovskaya. A woman member of her\ncampaign faced threats of sexual violence by police."},{"id":"a-hrc-49-71-p0018","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"18","seq":19,"section":"IV. Pre-election period (1 May to 8 August 2020)","text":"Large-scale demonstrations erupted in May and June 2020. On 24 May, hundreds of\nprotesters held slippers as a sign of protest against President Lukashenko’s candidacy,\nfollowed by countrywide protests, which were violently dispersed by police (A/HRC/46/4,\npara. 20)."},{"id":"a-hrc-49-71-p0019","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"19","seq":20,"section":"IV. Pre-election period (1 May to 8 August 2020)","text":"The pre-election period was further characterized by the repression of activists, human\nrights defenders, non-governmental organizations and journalists."},{"id":"a-hrc-49-71-p0020","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"20","seq":21,"section":"V. Election and immediate aftermath (9 to 14 August 2020)","text":"In response to the incumbent President’s declaration of victory on 9 August 2020,\npeople took to the streets over the following days to peacefully protest the way the election\nhad been conducted and votes counted at polling stations. Hundreds of thousands of people\nrallied to voice their opposition to the widely contested result."},{"id":"a-hrc-49-71-p0021","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"21","seq":22,"section":"V. Election and immediate aftermath (9 to 14 August 2020)","text":"Representing the largest anti-government movement in the history of Belarus, protests\n– including women’s marches – were held in all six oblasts and brought together people from\nall walks of life, men, women, children, pensioners and students, frequently expressing their\nresistance by acts of carrying white-red-white flags and flowers and wearing white ribbons.\nThe Government responded with a massive and violent crackdown."},{"id":"a-hrc-49-71-p0022","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"22","seq":23,"section":"A. Unnecessary and disproportionate use of force","text":"After the voting ended on the evening of 9 August, people gathered peacefully in the\ncentre of Minsk and other cities across Belarus. Protesters in Minsk gathered over several\ndays, primarily around the victory memorial on Masherova Avenue (commonly known as\n“Stela”), Victory Square and Pushkin Square. As the gatherings grew, protesters were met\nwith a heavy-handed response by security forces. In an effort to check the spread of the\nprotests, security forces blocked the main roads leading into Minsk, and Internet access was\nblocked countrywide for at least 61 hours (A/HRC/46/4, para. 35)."},{"id":"a-hrc-49-71-p0023","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"23","seq":24,"section":"A. Unnecessary and disproportionate use of force","text":"Between 9 and 14 August, various State security forces were involved in responding\nto the protests, including members of the Militsiya; the Special Purpose Police Detachment\n(OMON); the Almaz Special Anti-terrorism Unit; the Main Directorate for Combating\nOrganized Crime and Corruption (GUBOPiK); the Internal Troops; the State Security\nCommittee of Belarus (KGB); and the Presidential security service (see annex I). Men\nwithout insignia, wearing balaclavas, also took part in the forced dispersals of protests,\ncreating a climate of fear and lawlessness."},{"id":"a-hrc-49-71-p0024","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"24","seq":25,"section":"A. Unnecessary and disproportionate use of force","text":"From all available information it examined, OHCHR concluded that the protests were\noverwhelmingly peaceful in character. Some witnesses recounted that they had\ncommunicated their peaceful intent directly to the riot police present, offering them flowers.\nOHCHR received credible information that, between 9 and 14 August, four service members\nwere injured while performing their duties. It found that isolated acts of violence such as\nthese were not sufficient to characterize the assemblies as a whole as non-peaceful.9 No\nindication was found that the security forces made any attempt to communicate with\ndemonstrators or to issue appropriate warnings before using water cannons, firing rubber\nbullets or launching stun grenades to forcibly disperse crowds."},{"id":"a-hrc-49-71-p0025","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"25","seq":26,"section":"A. Unnecessary and disproportionate use of force","text":"Almost all interviewees described OMON riot police beating protesters and passers-\nby randomly with batons during dispersal. According to several witnesses, security forces in\nMinsk and elsewhere stopped cars and forced people out of them, beat the people and then\ndetained them. Several individuals were beaten until they lost consciousness. During the\nexamination, OHCHR documented tramline bruises consistent with beating by batons. In the\nmajority of cases, these injuries were on the rear side of victims’ bodies, indicating that they\nhad not been confronting security forces at the moment of being struck. This conclusion was\ncorroborated by open-source video footage, human rights organizations and media. Such\ntreatment, depending on its severity and particular circumstances, could meet the threshold\nof torture or other ill-treatment (see para. 46 below)."},{"id":"a-hrc-49-71-p0026","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"26","seq":27,"section":"A. Unnecessary and disproportionate use of force","text":"Water cannons and tear gas should be used only as a measure of last resort, with prior\nverbal warning, and only if there is clear evidence of an imminent threat of serious violence. 10\nOHCHR documented the widespread use of both means to disperse peaceful protesters."},{"id":"a-hrc-49-71-p0027","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"27","seq":28,"section":"A. Unnecessary and disproportionate use of force","text":"OHCHR also documented the unnecessary and disproportionate use of crowd control\nagents, such as kinetic impact projectiles and stun grenades during the protests held between\n9 and 14 August. Rubber bullets were fired into crowds, without warning; during the protests,\nfor example, one woman in Minsk was shot at and a rubber bullet penetrated her briefcase.\nAnother person saw OMON officers jumping out of a minivan, shooting what the witness\nbelieved to be rubber bullets at passengers who were leaving a taxi. The officers also shot at\ncars with passengers still inside."},{"id":"a-hrc-49-71-p0028","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"28","seq":29,"section":"A. Unnecessary and disproportionate use of force","text":"OHCHR received credible information, including medical reports reviewed by an\nindependent forensic medical expert, that rubber-coated steel bullets were used by the\nsecurity forces firing directly at protesters. As evidenced by the type of injuries, these were\nfired at short range or in proximity, severely injuring numerous protesters."},{"id":"a-hrc-49-71-p0029","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"29","seq":30,"section":"A. Unnecessary and disproportionate use of force","text":"OHCHR also documented a widespread pattern of the use of stun grenades against\ndemonstrators. Security forces started shooting at the crowd, and at least one stun grenade\nwas fired directly at them. Riot police used water cannons, then immediately followed up by\nthrowing stun grenades into a crowd of protesters. OHCHR found reasonable grounds to\nbelieve that, in a number of cases it documented, security forces threw or launched stun\ngrenades directly at individuals, causing major, life-threatening injuries."},{"id":"a-hrc-49-71-p0030","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"30","seq":31,"section":"A. Unnecessary and disproportionate use of force","text":"On the basis of an analysis of 26 first-hand witness accounts, their medical records\nand photographic material, in conjunction with a review of the injuries of more than 1,000\nindividuals treated by the Minsk medical emergency services during the protests, along with\nopen source material, OHCHR found that injuries resulting from the use of force in several\ncities across Belarus between 9 and 12 August included tramline bruises and hematoma on\nthe torso, buttocks and back of the legs, head injuries (such as brain contusion), concussion,\ntraumatic wounds, fractures and burns, ear drum perforations as a result of acoustic trauma\nand eye injuries. More severe injuries included multiple organ injuries sustained from rubber-\ncoated steel bullets and internal organ damage caused by shrapnel from stun grenade\nfragments and burns caused by explosions."},{"id":"a-hrc-49-71-p0031","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"31","seq":32,"section":"A. Unnecessary and disproportionate use of force","text":"OHCHR also reviewed information concerning at least three deaths allegedly the\nresult of unnecessary or disproportionate force during the protests. They included Aleksandr\nTaraykovsky (shot in the chest, allegedly by a rubber bullet, in Minsk on 10 August);\nAleksandr Vikhor (died in custody in Gomel on 12 August); and Gennady Shutov (allegedly\nshot in the head by a plainclothes police officer in Brest on 11 August, and died in hospital\non 19 August). The authorities have denied responsibility for these killings, yet failed to\nconduct effective investigations into them, according to information collected by OHCHR\nduring its examination."},{"id":"a-hrc-49-71-p0032","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"32","seq":33,"section":"A. Unnecessary and disproportionate use of force","text":"The authorities claim that the dispersal of the protests was decided in the pursuit of\npublic order objectives. OHCHR, however, found no information to indicate that the protests\nas such were violent or caused serious and sustained disruption of the kind that could justify\nforcible dispersal.11 Rather, the disproportionate force appears to have been designed to\ngenerally suppress expression of dissent, to intimidate the population and to shield the\nincumbent Government from criticism, which are not legitimate objectives."},{"id":"a-hrc-49-71-p0033","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"33","seq":34,"section":"A. Unnecessary and disproportionate use of force","text":"While the exact number of people subjected to violence at the hands of State\nauthorities cannot be determined, it may be reasonably estimated as being in the thousands.\nThe nature of security forces’ responses also violated the freedoms of expression and of\npeaceful assembly of hundreds of thousands of Belarusians."},{"id":"a-hrc-49-71-p0034","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"34","seq":35,"section":"A. Unnecessary and disproportionate use of force","text":"Furthermore, OHCHR has reasonable grounds to believe that the decision to use force\nagainst peaceful protesters was made at a high level within the Government and was\nimplemented with a high degree of coordination. On 28 July 2020, the President instructed\nthe head of Minsk OMON Dmitry Balaba to be heavy-handed on protesters. On 6 August,\nthe Minister of the Interior, Yury Karaev, met with the regional heads of police and, referring\nto orders from the commander in chief and threatening consequences if the orders were not\nfollowed, instructed them to prevent people from assembling and to detain them. The\nleadership of GUBOPiK assigned officers to “attack teams”, jointly with the military, to\ncrack down on protests. On 11 August, the deputy head of Minsk regional police instructed\nthe use of physical force and special equipment, and to beat and detain anyone “talking on\nthe phone” or standing in a group of five “at a bus stop”."},{"id":"a-hrc-49-71-p0035","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"35","seq":36,"section":"B. Arbitrary arrest and detention","text":"Article 9 of the International Covenant on Civil and Political Rights prohibits arbitrary\narrest or detention, and requires that deprivation of liberty be conducted on grounds and in\naccordance with procedures prescribed by law. “Arbitrariness” includes elements of\ninappropriateness, injustice, lack of predictability and due process of law, and elements of\nreasonableness, necessity and proportionality. Arrest or detention as punishment for the\nlegitimate exercise of the rights to freedoms of opinion and expression, freedoms of assembly\nand association or on discriminatory grounds, is arbitrary.12"},{"id":"a-hrc-49-71-p0036","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"36","seq":37,"section":"B. Arbitrary arrest and detention","text":"During its examination, OHCHR found that, between May 2020 and May 2021, at\nleast 37,000 people were arbitrarily arrested and detained; between 9 and 14 August alone,\napproximately 13,500 were arrested (11,800, 1,000 women and 700 children). During those\nsix days, arrests were made in more than 100 cities, towns and villages throughout Belarus,\n4,616 in Minsk alone. In the rest of the country, more than 860 were made in Brest, more\nthan 850 in Grodno, some 800 in Vitebsk, some 700 in Mogilev and roughly 650 in Gomel."},{"id":"a-hrc-49-71-p0037","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"37","seq":38,"section":"B. Arbitrary arrest and detention","text":"Of the 4,616 people arrested in Minsk between 9 and 14 August, 4,254 (92 per cent)\nwere detained under article 23.34 of the Code of Administrative Offences for “participation\nin an unauthorized mass event”, a direct sanction for violations of the Law on Mass Events,\na law that fails to meet international standards (A/HRC/46/4, paras. 31–32 and 78).13 Arrests\nand detentions under this offence for the legitimate exercise of the rights to freedom of\nopinion and expression, freedom of assembly, and freedom of association are arbitrary."},{"id":"a-hrc-49-71-p0038","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"38","seq":39,"section":"B. Arbitrary arrest and detention","text":"The massive number of arrests and cases of detention in reaction to the peaceful\nprotests reached a scale unprecedented in Belarus. From the testimonies received by\nOHCHR, it appeared that arrests had mostly been made at random, and that security forces\nhad chased and seized people they could catch, including passers-by and persons who were\ndragged out of cars and shops. In addition, certain persons with an “alternative appearance”\n(e.g., men with long hair or persons with tattoos) were specifically targeted."},{"id":"a-hrc-49-71-p0039","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"39","seq":40,"section":"B. Arbitrary arrest and detention","text":"Interviewees referred to having spent hours after their arrest in police vehicles,\nincluding being kept standing, or driven to another part of town, transferred to another\nvehicle, and forced to wait in a courtyard or a sport halls of police station or detention\nfacilities, sometimes even overnight, before their arrest was effectively registered. Victims\ndescribed how, during that time, they were routinely severely beaten and subjected to torture\nand other forms of ill-treatment."},{"id":"a-hrc-49-71-p0040","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"40","seq":41,"section":"B. Arbitrary arrest and detention","text":"OHCHR found that detainees were denied basic safeguards: they were not informed\nof the reasons for their arrest nor of the charges against them, were not able to communicate\nwith their relatives who were often denied information about their whereabouts, and were\nmostly denied medical assistance, even when they were injured. They were also not provided\nlegal assistance, and lawyers were denied access to them."},{"id":"a-hrc-49-71-p0041","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"41","seq":42,"section":"B. Arbitrary arrest and detention","text":"Many witnesses informed OHCHR that they were not allowed to read the police\nreports. Those who demanded to read them or refused to sign were beaten or threatened,\nincluding with rape. Many were forced to sign a document stating that they would not\nparticipate in protests. A number of people were released without being charged after\nspending up to 72 hours in custody without judicial oversight – a length of time that is\nunjustified, even though in line with domestic law, and has been identified by the Human\nRights Committee as a violation of article 9.3 of the International Covenant on Civil and\nPolitical Rights, including for administrative minor offences.14 Moreover, these detentions\nwere ordered for “participation in an unauthorized assembly”, in itself arbitrary."},{"id":"a-hrc-49-71-p0042","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"42","seq":43,"section":"B. Arbitrary arrest and detention","text":"The examination revealed that, between 9 and 14 August, Belarusian security forces\narrested and detained a large number of people solely for having participated in a peaceful\nprotest and exercised their right to freedom of expression as punishment and to intimidate\nthe population. OHCHR has reasonable grounds to believe that there were widespread\nviolations of the prohibition of arbitrary arrest or detention."},{"id":"a-hrc-49-71-p0043","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"43","seq":44,"section":"C. Torture and other cruel, inhuman or degrading treatment or","text":"Torture, and inhuman or degrading treatment or punishment, are prohibited by both\nthe Convention against Torture and article 7 of the International Covenant on Civil and\nPolitical Rights. This prohibition is non-derogable and absolute.15 Article 1 of the Convention\nagainst Torture defines the constitutive elements of torture as the intentional infliction of\nsevere pain or suffering through an act, or omission of an act, that pursues a purpose,\nincluding punishment, intimidation or obtaining information or a confession, or is based on\ndiscrimination, and the involvement, instigation, consent or acquiescence of a public official."},{"id":"a-hrc-49-71-p0044","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"44","seq":45,"section":"C. Torture and other cruel, inhuman or degrading treatment or","text":"Those detained between 9 and 14 August were subjected to prolonged and repeated\nbeatings with batons during transport in security force vehicles (avtozak) and at police\nstations and detention facilities; made to run from the vehicles to the buildings past a line-up\nof security forces who beat them with batons as they passed (“corridors”); and were made to\nstay for hours in stress positions in courtyards and hallways of police stations and detention\nfacilities, such as standing facing the wall, kneeling on their knees and elbows or lying with\ntheir hands tied behind the back for hours, face down, on the ground."},{"id":"a-hrc-49-71-p0045","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"45","seq":46,"section":"C. Torture and other cruel, inhuman or degrading treatment or","text":"Pleas for medical help, water, food and access to a lavatory were largely ignored, and\ndetainees were often beaten to dissuade them from complaining. Persons already visibly\ninjured were still subject to beating or even electroshock with stun weapons, often in their\ninjured and swollen body parts, causing particularly excruciating pain. The degree and\nseverity of the ill-treatment were often determined by law enforcement officials on the basis\nof the persons’ appearance, or the colour marks and symbols drawn on their bodies by\nsecurity forces during their arrest. Furthermore, OHCHR found that men were raped and that\nother forms of sexual and gender-based violence were used against men and women in\ndetention (see paras. 75-79 below)."},{"id":"a-hrc-49-71-p0046","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"46","seq":47,"section":"C. Torture and other cruel, inhuman or degrading treatment or","text":"Officials called ambulances only for the most serious medical cases. Witnesses heard\nofficials discussing whether it was too late to take a person to hospital, and saying “stop now,\nyou’ll kill him”, indicating their awareness of the severity of torture and ill-treatment they\nwere causing."},{"id":"a-hrc-49-71-p0047","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"47","seq":48,"section":"C. Torture and other cruel, inhuman or degrading treatment or","text":"Some detainees were forced to walk on a white-red-white flag, to sing the Belarusian\nnational anthem, to repeat pro-government slogans or to chant “I love OMON”. In some\ncases, detainees were tortured or abused to force them to unlock their mobile phones or reveal\ntheir passwords or other information."},{"id":"a-hrc-49-71-p0048","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"48","seq":49,"section":"C. Torture and other cruel, inhuman or degrading treatment or","text":"Detainees were kept in inhumane conditions regardless of COVID-19 precautions\nwhen being transported in overcrowded and unventilated security vehicles, thrown on top of\neach other or locked together in metal compartments (stakan) designed for one detainee, and\nin detention facilities. Those detained in Okrestino and Zhodino stated that between 30 and\n50 detainees were packed into cells designed for seven or eight people, without adequate\nventilation or sanitation, and were given one bottle of water to share among all of them. They\nwere furthermore denied food for prolonged periods, and were unable to sleep or lie down\nowing to lack of beds or space. Detainees and insider sources spoke of having to listen to\npeople being beaten and screaming in neighbouring cells or hallways."},{"id":"a-hrc-49-71-p0049","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"49","seq":50,"section":"C. Torture and other cruel, inhuman or degrading treatment or","text":"OHCHR found that the practices of torture and ill-treatment used in a number of\ndetention facilities in Minsk,16 were adopted also in other cities, and that these were not\nrandom occurrences."},{"id":"a-hrc-49-71-p0050","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"50","seq":51,"section":"C. Torture and other cruel, inhuman or degrading treatment or","text":"A forensic analysis undertaken by an examination of testimonies, photographic\nmaterials and medical records showed a multitude of tramline bruises, extensive and severe\necchymosis, bone fractures, concussions and cranial trauma. These findings aligned with the\nforensic analysis of 70 torture cases received as secondary material collected by Belarusian\ndoctors."},{"id":"a-hrc-49-71-p0051","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"51","seq":52,"section":"C. Torture and other cruel, inhuman or degrading treatment or","text":"During its examination work, OHCHR also analysed the cases and associated findings\nmade by the International Rehabilitation Council for Torture Victims, which were based on\na thorough forensic examination of 50 victims from different cities in Belarus detained during\nthe same period and selected at random from the 1,500 interviews and cases in the database\nof the International Committee for Investigation of Torture in Belarus. The practices and\ninjuries identified by the Council corroborate the findings made by OHCHR. It also found\nthe 636 cases of torture documented and analysed by the non-governmental human rights\norganization Viasna to be credible. Furthermore, the testimonies of victims and witnesses\ncollected in the context of the examination corroborated the numerous accounts of torture,\nill-treatment and inhumane conditions of detention documented and analysed by other\norganizations, including those of the Organization for Security and Co-operation in Europe\n(OSCE) Moscow Human Dimension Mechanism. These analyses lend further credence to\nthe findings made by OHCHR that torture and ill-treatment were used systematically as a\ntool to punish and intimidate detainees."},{"id":"a-hrc-49-71-p0052","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"52","seq":53,"section":"C. Torture and other cruel, inhuman or degrading treatment or","text":"OHCHR was able to corroborate through multiple, independent and credible sources\nthat, in police stations and detention facilities, higher-ranking officials gave orders to beat\ndetainees harder and more frequently, and selected detainees to receive harsher treatment.\nThis confirms that persons arrested during the protests were subjected to torture and ill-\ntreatment upon orders."},{"id":"a-hrc-49-71-p0053","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"53","seq":54,"section":"C. Torture and other cruel, inhuman or degrading treatment or","text":"The information collected indicates that security forces acted upon orders and with an\nobjective, pointing to a widespread and systematic practice of torture and ill-treatment that\nwas largely punitive in nature against individuals for their real or perceived opposition to the\nGovernment or the election results. There are reasonable grounds to believe that the acts\ncommitted in custody by Belarusian security forces between 9 and 14 August 2020, in Minsk\nand other cities, qualify as torture or cruel, inhuman or degrading treatment or punishment\nunder applicable international standards.17"},{"id":"a-hrc-49-71-p0054","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"54","seq":55,"section":"D. Failure to effectively investigate allegations of torture and ill-treatment","text":"International human rights law establishes the legal duty of States to investigate,\nprosecute and punish acts of torture or cruel, inhuman or degrading treatment or punishment\nand to provide victims with effective remedy and redress. 18 OHCHR is not aware of any\ncriminal charges brought or convictions handed down for acts of violence by security forces\nagainst protesters or persons in detention."},{"id":"a-hrc-49-71-p0055","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"55","seq":56,"section":"D. Failure to effectively investigate allegations of torture and ill-treatment","text":"OHCHR was able to speak to a number of persons who submitted complaints of\ntorture or ill-treatment to the Investigative Committee (see annex I, para.13) following their\nrelease from detention and who were subsequently informed that their complaints had been\ndismissed. Many victims were afraid to file a complaint, and several of them who did stated\nthat they were later subjected to reprisals. In a number of cases, following their complaints,\ncriminal and administrative charges were brought against the complainants for participating\nin protests (A/HRC/46/4, para. 73). Others stated that, upon their release, they were\ndiscouraged from filing a complaint. On 14 August 2020, the Deputy Minister of the Interior,\nAleksandr Barsukov, publicly denied that State security forces had engaged in any acts of\ntorture. On 2 November, Mikhail Vavulo, head of the International Legal Department of the\nInvestigative Committee, informed the Human Rights Council that the Committee was not\ninvestigating any allegations of police abuse because “currently no cases of unlawful acts by\nthe police had been identified.”"},{"id":"a-hrc-49-71-p0056","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"56","seq":57,"section":"D. Failure to effectively investigate allegations of torture and ill-treatment","text":"On 26 August 2021, the Investigative Committee announced that it had completed its\nexamination of around 5,000 complaints relating to ill-treatment received in summer/autumn\n2020, all of which had been rejected as “unconfirmed”, and that allegations of abuse of office,\ntorture and sexual abuse had also not been confirmed. In an interview published on the\nwebsite of the Investigative Committee, its Deputy Chairman, Anatoly Vasiliev, admitted the\nuse of stress positions and beatings “with rubber batons” in detention facilities. He also\nlabelled the complainants as “drunkards”, “liars” and people with criminal records who\nthought that by filing complaints they could avoid prosecution."},{"id":"a-hrc-49-71-p0057","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"57","seq":58,"section":"D. Failure to effectively investigate allegations of torture and ill-treatment","text":"On 19 November 2021, President Lukashenko admitted that persons had been beaten\nin the Okrestino detention centre after the election, adding however that “police officers had\nbeen beaten up too”. The repeated calls for effective and independent investigations into\nallegations of torture and ill-treatment, including by the High Commissioner19 and the special\nprocedures of the Human rights Council,20 have gone unheeded by Belarusian authorities.\nThe conclusions of the Investigative Committee, taken together with the discourse of\nofficials, provide reasonable grounds to believe that allegations of torture have not been\neffectively investigated, in violation of the State’s obligations under article 7 of the\nInternational Covenant on Civil and Political Rights and articles 12 to 14 of the Convention\nagainst Torture."},{"id":"a-hrc-49-71-p0058","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"58","seq":59,"section":"E. Rights to due process and to a fair trial","text":"In a further effort to intimidate and supress political opposition and dissent, tens of\nthousands of people were charged under article 23.34 and other administrative offences, in\nparticular from 9 to 14 August 2020, and hundreds with criminal offences."},{"id":"a-hrc-49-71-p0059","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"59","seq":60,"section":"E. Rights to due process and to a fair trial","text":"From 9 to 14 August, “conveyor belt” summary administrative trials were held in\ndetention facilities in closed hearings, which lacked basic procedural guarantees and –\naccording to the defendants – often lasted only a few minutes. With few exceptions, the\njudges ignored defendants, despite their visible injuries, when they tried to assert that they\nhad been tortured or ill-treated."},{"id":"a-hrc-49-71-p0060","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"60","seq":61,"section":"E. Rights to due process and to a fair trial","text":"During its examination, OHCHR noted numerous violations of the rights to due\nprocess and to a fair trial in both administrative and criminal cases. Lawyers’ access to their\nclients was obstructed, defendants were not able to talk to their lawyers confidentially, and\nlawyers were denied adequate access to files or sufficient time to consult them and prepare\ntheir defence. Prosecution witnesses often testified anonymously via Skype."},{"id":"a-hrc-49-71-p0061","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"61","seq":62,"section":"E. Rights to due process and to a fair trial","text":"In criminal cases, in particular those of high-profile dissidents, hearings were closed,\nand defence lawyers were forced to sign non-disclosure agreements. Lawyers who defended\nsuch cases or spoke out about human rights violations and the lack of rule law or who brought\ncases to United Nations human rights mechanisms were deprived of their liberty, harassed\nand intimidated, and faced disbarment and disciplinary sanctions. Since the election and as\nat November 2021, 36 lawyers have been deprived of their licenses either through disbarment\nor loss of certification, under procedures enabled by the lack of independence of the Bar\nAssociation and the broad control of the Ministry of Justice over the legal profession.\nAmendments to the Law on Bar and Lawyers, which came into force in November 2021,\nextended the Ministry’s powers in this area further still. The intimidation and punishment of\nindependent lawyers has a serious chilling effect on the legal profession and effectively\ndeprives victims of human rights violations of the right to a fair hearing and access to justice."},{"id":"a-hrc-49-71-p0062","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"62","seq":63,"section":"VI. Post-election period","text":"After the election, the Government continued to persecute those seeking to exercise\ntheir rights to freedom of expression, peaceful assembly, association and to participate in\npublic affairs. Between September and December 2020, peaceful protests continued, despite\nthe fact that they were systematically and often violently dispersed, ending in arrests and\ndetentions."},{"id":"a-hrc-49-71-p0063","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"63","seq":64,"section":"VI. Post-election period","text":"In September 2020, the authorities also began to press charges against members of the\nopposition Coordination Council, human rights defenders, journalists, lawyers, and ordinary\ncitizens who had participated in peaceful protests or expressed criticism. This trend continued\nthroughout 2021. Interviewees, including some who had filed complaints of torture or ill-\ntreatment, described how in spring and summer 2021 they were taken in for questioning and\ndeclared suspects or charged in criminal cases related to the 2020 protests."},{"id":"a-hrc-49-71-p0064","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"64","seq":65,"section":"VI. Post-election period","text":"Criminal charges were mostly brought under articles 293.1 (“organization of mass\nriots”), 342.1 (“organization of or participation in actions that grossly violate public order”)\nand 130.1 (“incitement to social discord”) of the Criminal Code."},{"id":"a-hrc-49-71-p0065","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"65","seq":66,"section":"VI. Post-election period","text":"On 23 May 2021, the authorities compelled the landing of Ryanair flight FR4978 and\narrested passengers Roman Protasevich, the former editor-in-chief of Telegram channel\nNEXTA, and his partner Sofia Sapega. Mr. Protasevich was also charged under articles\n293.1, 342.1 and 130.1 of the Criminal Code and Ms. Sapega under art. 130.1, facing up to\n15 and six years in prison, respectively. In its opinion No. 50/2021, the Working Group on\nArbitrary Detention concluded that Mr. Protasevich’s detention was arbitrary and based on\nhis exercise of freedom of expression.21"},{"id":"a-hrc-49-71-p0066","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"66","seq":67,"section":"VI. Post-election period","text":"In the second quarter of 2021, the Government passed a raft of legislative\namendments, further undermining the exercise of fundamental freedoms. These laws were\ndeveloped in response to “the events of past year”, according to the Head of the Presidential\nAdministration. The Administrative Code of Offences and the Criminal Code were also\namended, introducing new offences and harsher sentences."},{"id":"a-hrc-49-71-p0067","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"67","seq":68,"section":"VI. Post-election period","text":"Amendments to the Law on Mass Events and the Law on Mass Media included\nadditional provisions that do not meet international standards. Both laws ban journalists from\nreporting on unauthorized protests, equating them to participants.22"},{"id":"a-hrc-49-71-p0068","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"68","seq":69,"section":"VI. Post-election period","text":"The amendment to the Law on Countering Extremism adopted on 14 May 2021\nbroadened the scope to persecute those expressing dissenting views by introducing individual\ncriminal liability and expanding the list of “extremists” and “extremist activities and\nmaterials”, which now includes possessing or displaying historical symbols and national\nattributes, such as the white-red-white flag. Article 361.1 of the Criminal Code (“creation of\nan extremist group or participation in it”) carries up to 10 years in prison."},{"id":"a-hrc-49-71-p0069","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"69","seq":70,"section":"VI. Post-election period","text":"OHCHR found that, by May 2021, the authorities had cracked down on the remaining\nindependent mass media outlets. On 18 May, the website of Tut.by, a popular news web\nportal, was blocked, a criminal case was opened for tax fraud against the media company and\n15 journalists were detained. On 13 August, its websites, social media and logos were\ndeclared “extremist materials”. On 8 July, authorities blocked three news websites, including\nNasha Niva, one of oldest media outlets in Belarus, conducted more than 20 searches and\narrested 11 journalists."},{"id":"a-hrc-49-71-p0070","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"70","seq":71,"section":"VI. Post-election period","text":"In November, BelaPAN news agency and Belsat TV were declared “extremist”\norganizations, as was Radio Free Europe/Radio Liberty in December. By the end of 2021,\n170 Telegram channels and 13 media outlets were also declared “extremist”, 146 raids had\nbeen made on offices and journalists’ homes, and 32 journalists were detained. In October,\nGUBOPiK warned that subscribing to such a channel carried criminal liability for\nparticipation in an “extremist formation”."},{"id":"a-hrc-49-71-p0071","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"71","seq":72,"section":"VI. Post-election period","text":"The authorities also massively cracked down on civil society and human rights\norganizations. Between September 2020 and July 2021, seven members of Viasna were\ndetained on criminal charges and remain in pretrial detention, and seven more are suspects\nin criminal cases. On 14 July 2021, 50 raids were undertaken at offices and homes of human\nrights defenders, and 20 persons were detained. By October 2021, some 270 non-\ngovernmental organizations had been closed down, including the Belarusian Helsinki\nCommittee, the oldest human rights organization in Belarus. This is the result of what appears\nto have been a concerted effort to eliminate any credible independent human rights work on\nviolations and on countering impunity in Belarus. In a public interview with the BBC in\nNovember 2021, President Lukashenko, in response to a question on the closures of non-\ngovernmental organizations, replied that “We’ll massacre all the scum that you [the West]\nhave been financing”.23"},{"id":"a-hrc-49-71-p0072","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"72","seq":73,"section":"VI. Post-election period","text":"On 26 July, the Prosecutor General announced that 4,200 criminal cases had been\nopened in relation to extremism and terrorism. Charges of tax evasion, which had been\nregularly used in the past to imprison critics and defenders, were also brought against\njournalists and human rights defenders.24"},{"id":"a-hrc-49-71-p0073","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"73","seq":74,"section":"VI. Post-election period","text":"By the end of 2021, 969 persons (858 men and 111 women) were in prison on what\nOHCHR has reasonable grounds to believe to be politically motivated charges. Of those\nsentenced, several received prison terms of 10 years or more: for example, Maria\nKolesnikova was sentenced to 11 years, and opposition leaders Sergey Tikhanovsky, Nikolay\nStatkevich and Igor Losik were sentenced to 18, 14 and 15 years, respectively. The Working\nGroup on Arbitrary Detention declared Mr. Tikhanovsky’s deprivation of liberty arbitrary\nand related to the peaceful exercise of his rights.25"},{"id":"a-hrc-49-71-p0074","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"74","seq":75,"section":"VI. Post-election period","text":"According to information received by OHCHR, since the election, at least some\n100,000 individuals have sought safety abroad, mainly in other European countries. In\nnumerous instances, interviewees expressed fear that their family members left behind were\nbeing harassed or intimidated by the authorities."},{"id":"a-hrc-49-71-p0075","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"75","seq":76,"section":"VII. Sexual and gender-based violence","text":"Sexual and gender-based violence, including psychological violence, was regularly\nused against both women and men in detention to intimidate and punish protesters and those\nperceived as pro-opposition. The Special Rapporteur on the situation of human rights in\nBelarus has expressed concern that hundreds of women have been subjected to torture, ill-\ntreatment and other forms of physical and psychological pressure while in detention,\nincluding gender-based violence and the threat of rape (A/76/145, para. 9). Acts of\nintimidation, including verbal insults, sexist and homophobic language were largely directed\nat women and individuals perceived as belonging to the LGBTIQ+ community."},{"id":"a-hrc-49-71-p0076","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"76","seq":77,"section":"VII. Sexual and gender-based violence","text":"Upon intake, women and men were typically forced to strip naked and repeatedly\nsubjected to intrusive intimate searches. Men were often forced to kneel and bend over face\nto the ground for prolonged periods of time. Guards, including female guards, kicked the\nkneeling detainees’ genital areas."},{"id":"a-hrc-49-71-p0077","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"77","seq":78,"section":"VII. Sexual and gender-based violence","text":"Sexual and gender-based violence was often directed by men towards men. Male\ndetainees spoke of anal penetration with batons amounting to rape, as well as having their\ngenitals grabbed or twisted. Injuries documented by medics corroborate accounts of such\npenetration. Medical records reviewed by OHCHR also indicated traumatic injuries to male\ngenitalia, including lesions, multiple abrasions and contusions. Sexist and homophobic\nremarks directed against the victims during torture confirm that sexual violence against men\nwas used to deliberately humiliate, assert power over and emasculate them, as a form of\npunishment for perceived political allegiances."},{"id":"a-hrc-49-71-p0078","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"78","seq":79,"section":"VII. Sexual and gender-based violence","text":"Overt threats of sexual violence were directed at both female and male detainees.\nSecurity officers made threats of physical and/or sexual abuse to female detainees’ minor\nchildren during interrogations. Parents, and in particular mothers, were threatened with the\nremoval of their children by social services for participating in the protests."},{"id":"a-hrc-49-71-p0079","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"79","seq":80,"section":"VII. Sexual and gender-based violence","text":"Individuals not perceived as “mainstream” – including LGBTIQ+ persons and those\nperceived to be – were significantly more likely to be singled out for especially cruel,\ninhuman or degrading treatment in detention or during house raids. In September 2020, a\nnumber of LGBTIQ+ rights activists were arbitrarily detained."},{"id":"a-hrc-49-71-p0080","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"80","seq":81,"section":"VIII. Conclusions under applicable international law","text":"On 24 September 2021, the High Commissioner noted that the Government’s\nresponse to the contested election in Belarus had the primary aim to suppress criticism and\ndissent of governmental policies rather than the protection of public order.26 This conclusion\nwas corroborated by the examination conducted, which also pointed to an active policy to\nprevent truth, justice and accountability for violations committed."},{"id":"a-hrc-49-71-p0081","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"81","seq":82,"section":"VIII. Conclusions under applicable international law","text":"As detailed in the preceding sections of the present report, OHCHR has reasonable\ngrounds to believe that a number of violations of international human rights law have been\ncommitted. The coordinated responses to the peaceful protests of 9 to 14 August 2020, at\nleast, including the unlawful use of less-lethal weapons against protesters, resulting in serious\ninjuries or deaths, provides reasonable grounds to believe that security forces systematically\nengaged in unnecessary or disproportionate force with the illegitimate aims of suppressing\nprotests and the expression of differing political viewpoints."},{"id":"a-hrc-49-71-p0082","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"82","seq":83,"section":"VIII. Conclusions under applicable international law","text":"There are reasonable grounds to believe that the response by the authorities to the\nprotests between 9 and 14 August 2020 also aimed to curtail the exercise of a range of\nfundamental rights and freedoms, with security forces repeatedly violating the rights to\nfreedom of expression, peaceful assembly and association. The countrywide Internet\nshutdown from 9 to 12 August also constituted a violation of the freedom of expression,\nwhich includes the right to seek and receive information, offline and online, and of the right\nof peaceful assembly.27"},{"id":"a-hrc-49-71-p0083","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"83","seq":84,"section":"VIII. Conclusions under applicable international law","text":"Individuals were targeted following a consistent pattern of unnecessary or\ndisproportionate use of force, arrests, detention (including incommunicado detention), and\ntorture or ill-treatment, including rape and sexual and gender-based violence, and the\nsystematic denial of the rights to due process and to a fair trial. The failure to effectively\ninvestigate human rights violations, including allegations of torture or other ill-treatment, is\na contravention of the State’s obligations under international human rights law. Furthermore,\nOHCHR found that, besides the lack of investigation, there was an active policy to shield\nperpetrators and prevent accountability, reflected in the degree of reprisals, intimidation of\nvictims and witnesses, and attacks on lawyers and human rights defenders."},{"id":"a-hrc-49-71-p0084","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"84","seq":85,"section":"VIII. Conclusions under applicable international law","text":"OHCHR further notes that individual criminal responsibility can accrue under\ncustomary international law, where human rights violations rise to the level of international\ncrimes.28 In terms of the present analysis, crimes against humanity are perpetrated when\ncertain prohibited acts are committed as part of a widespread or systematic attack directed\nagainst any civilian population, with knowledge of the attack. 29 Such acts include\nimprisonment or other severe deprivation of physical liberty in violation of fundamental rules\nof international law; torture; rape and certain acts of sexual violence; and other inhumane\nacts of a similar character intentionally causing great suffering, or serious injury to body or\nto mental or physical health."},{"id":"a-hrc-49-71-p0085","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"85","seq":86,"section":"VIII. Conclusions under applicable international law","text":"By May 2021, some 37,000 persons had been arrested and detained in Belarus in the\ncontext of the election, including around 13,500 between 9 and 14 August 2020. These arrests\nand detentions, accompanied by the unlawful use of force that caused serious bodily injury\nand harm, and followed by torture and ill-treatment, including rape, were on a large scale and\nhad the effect of exerting pressure on the population, to stifle dissent and public displays of\nopposition to the incumbent President."},{"id":"a-hrc-49-71-p0086","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"86","seq":87,"section":"VIII. Conclusions under applicable international law","text":"Given the scale and patterns of the violations identified in the present report, their\nwidespread and systematic nature, and the evidence of official policy, knowledge and\ndirection in respect of their collective execution by multiple State organs, in particular\nregarding mass arbitrary detention in the period from 9 to 14 August 2020, there are sufficient\nindicia to warrant further assessment of the available evidence from the perspective of\napplicable international criminal law."},{"id":"a-hrc-49-71-p0087","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"87","seq":88,"section":"IX. Accountability","text":"In its resolution 46/20, the Human Rights Council stressed the need for accountability\nfor human rights violations in Belarus, and requested the High Commissioner to contribute\nto accountability for perpetrators and justice for victims."},{"id":"a-hrc-49-71-p0088","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"88","seq":89,"section":"IX. Accountability","text":"OHCHR notes that there are currently no effective remedies available domestically\nfor Belarusians subjected to the unnecessary use of force carried out between 9 and 14 August\n2020, nor for the tens of thousands of women, men and children arrested arbitrarily, subjected\nto torture and inhuman or degrading treatment, and denied the rights to due process and a fair\ntrial. IT is furthermore not aware of any efforts made by the authorities to hold alleged\nperpetrators to account, nor of the prosecution or trial of any members of the security forces.\nSuch conduct is also indicative of a State policy or practice of shielding perpetrators of human\nrights violations."},{"id":"a-hrc-49-71-p0089","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"89","seq":90,"section":"IX. Accountability","text":"Few meaningful avenues for justice remain for the victims within Belarus because of\nthe role of prosecutors and lack of independence of the judiciary, the denial of the right to a\nfair trial, and the intimidation to which lawyers are subjected. Systemic flaws in the rule of\nlaw facilitate the use of the judiciary as an instrument of repression and a means to avoid\naccountability for violations. Without effective investigations and remedies, currently there\nis no reasonable expectation for justice to be delivered for human rights violations committed\nin Belarus."},{"id":"a-hrc-49-71-p0090","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"90","seq":91,"section":"IX. Accountability","text":"As a State party to the International Covenant on Civil and Political Rights and the\nConvention against Torture, Belarus has an obligation to ensure that its competent authorities\nproceed to a prompt and impartial investigation wherever there are reasonable grounds to\nbelieve that an act of torture or ill-treatment has been committed in any territory under its\njurisdiction.30 Victims of torture also have the right to report a complaint and to have their\ncases promptly and impartially examined, and to protection against intimidation. 31 Moreover,\nvictims of all human rights violations have the right to reparation, including measures of\nsatisfaction and compensation."},{"id":"a-hrc-49-71-p0091","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"91","seq":92,"section":"IX. Accountability","text":"OHCHR notes that criminal investigations have been initiated in at least four\ncompetent jurisdictions outside Belarus in relation to the human rights violations and\npotential international crimes committed in Belarus.32 In this regard it is vital that efforts to\ncollect, document and preserve evidence of the violations continue with a view to assisting\nfuture accountability processes."},{"id":"a-hrc-49-71-p0092","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"92","seq":93,"section":"IX. Accountability","text":"Pursuant to relevant United Nations protocols, the material collected, preserved,\nanalysed and stored by OHCHR during its examination may be sought by national or\ninternational investigative or judicial authorities seeking to pursue accountability measures.33\nOpportunities to consider such cooperation within the United Nations framework for\nengagement with national authorities arise where informed consent to share statements,\nsupplementary material or other documentary evidence has been given by its provider, and\nwhere such accountability processes are consistent with international human rights standards."},{"id":"a-hrc-49-71-p0093","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"93","seq":94,"section":"X. Recommendations","text":"The High Commissioner recalls all the recommendations made in her previous\nreport to the Human Rights Council (A/HRC/46/4)."},{"id":"a-hrc-49-71-p0094","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"94","seq":95,"section":"X. Recommendations","text":"The High Commissioner further recommends that the Government of Belarus:\n(a)    Immediately release all prisoners sentenced on politically motivated\ngrounds and cease all other ongoing violations of human rights identified in the present\nreport, including the systematic repression of civil society, independent media and\nopposition groups, and refrain from committing such violations in the future;\n(b)    Promptly initiate effective, transparent and independent investigations\ninto all past violations of human rights that can be qualified as crimes under national\nor international law, including mass arbitrary arrest and detention, torture and other\nill-treatment, and the gender dimension of any such crimes, and ensure that\ninvestigations can cover the full chain of command that may bear individual criminal\nresponsibility;\n(c)     Provide full reparation, including compensation, restitution,\nrehabilitation, appropriate forms of satisfaction and guarantees of non-repetition to all\nvictims of human rights violations, in accordance with international and domestic law;\n(d)     Implement structural reforms that can enable the full realization of the\nright to participate in public affairs and other related civil and political rights, including\nthe freedoms of expression, peaceful assembly and association, for all Belarusians;\n(e)    Implement structural reforms that can enable the creation of an\nindependent judiciary free from executive influence that can serve as a guarantor of\nhuman rights and the rule of law, including respect for the independence of lawyers and\ntheir protection;\n(f)    Provide access to and ensure cooperation with OHCHR and all special\nprocedures of the Human Rights Council, including the Special Rapporteur on the\nsituation of human rights in Belarus;\n(g)    Give effect to the decisions of the Human Rights Committee in the context\nof individual communications under the Optional Protocol to the International\nCovenant on Civil and Political Rights and to the recommendations made by\ninternational human rights mechanisms, and refrain from any reprisal against those\nwho cooperate with United Nations mechanisms."},{"id":"a-hrc-49-71-p0095","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"95","seq":96,"section":"X. Recommendations","text":"The High Commissioner recommends that other States Members of the United\nNations:\n(a)     Engage with the Belarusian authorities through continuing dialogue, with\na view to ensure the State’s full compliance with its obligations under international\nhuman rights law, and in this context consider appropriate use of the opportunities\nprovided by the relevant international and regional human rights mechanisms to\nvindicate these obligations;\n(b)    Work towards accountability through national proceedings based on\naccepted principles of extraterritorial and universal jurisdiction, as relevant and in\naccordance with international law and, in combination, explore other targeted\nmeasures against credibly alleged perpetrators of grave human rights violations and\nabuses;\n(c)   Review, in this regard, their domestic legal systems with a view to\naddressing and removing structural barriers that may hinder effective investigations\nand prosecutions based on extraterritorial or universal jurisdiction, consistent with\ninternational law, including through any necessary legislative amendments and the\nprovision of adequate resources, personnel and training to the relevant investigative,\nprosecutorial and judicial authorities;\n(d)    Ensure effective cooperation with other States engaged in accountability\nefforts at the national level, including through effective coordination, information-\nsharing, provision of mutual legal assistance and extradition, as relevant;\n(e)    Fully respect the principle of non-refoulement, in particular with respect\nto human rights defenders, journalists and victims of human rights violations who have\nfled Belarus to their territories, and take measures to protect their rights and enable\nthem to lead dignified lives, including through the enjoyment of the right to work and\nby providing full access to public and social services in their territories, as well as to full\nrehabilitation services for victims of gross human rights violations, including torture;\n(f)    In view of the broad suppression of civil society in Belarus, consider\nsupporting civil society actors engaged with respect to Belarus in their efforts to\npromote and protect human rights in the country, including in the context of\naccountability for human rights violations;\n(g)    Consider supporting further efforts to document and preserve\ninformation and evidence of human rights violations committed in Belarus for the\npurposes of present and future accountability measures."},{"id":"a-hrc-49-71-p0001-a1","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"1","seq":97,"section":"Annex I","text":"The internal security sector of Belarus comprises the Ministry of Internal Affairs and\nthe Internal Troops subordinate to it; the Committee for State Security (KGB); the Operations\nand Analysis Centre under the President and the Presidential Security Service; the structures\nof the State Border Committee; the investigative division of the State Control Committee;\nthe State Customs Committee; and the Main Intelligence Directorate of the Belarusian Armed\nForces. While enough information is available to establish the involvement of the above-\nlisted agencies in the events that occurred during the 9 to 14 August period, only the key\nagencies of the security sector are listed here.","annex":1},{"id":"a-hrc-49-71-p0002-a1","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"2","seq":98,"section":"Annex I","text":"The Security Council is the supreme collective coordinating and enforcing the powers\nof the President on matters of national security. The President appoints the members of the\nCouncil who among others determine key national interests, real and potential external and\ninternal security threats, submit proposals to the President regarding domestic policies in\nensuring public security, put forward preventive measures to prevent emergency situations\nand coordinate activities of the government authorities.","annex":1},{"id":"a-hrc-49-71-p0003-a1","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"3","seq":99,"section":"Annex I","text":"The Presidential Security Service is responsible for ensuring the security of senior\nofficials of the Belarusian state and ensuring the security of protected objects.","annex":1},{"id":"a-hrc-49-71-p0004-a1","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"4","seq":100,"section":"Annex I","text":"The Ministry of Internal Affairs oversees the Penal Correction Department (PCD), the\nMain Directorate for Combatting Organized Crime and Corruption (GUBOPiK), the Internal\nTroops, and the Almaz Special Anti-Terrorism Unit.","annex":1},{"id":"a-hrc-49-71-p0005-a1","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"5","seq":101,"section":"Annex I","text":"The Penal Correction Department (PCD) oversees all Ministry of Internal Affairs’\ndetention facilities.34 The head of the PCD is nominated by the Minister of Internal Affairs\nand appointed by the President. The head of the PCD reports directly to the Minister of\nInternal Affairs.","annex":1},{"id":"a-hrc-49-71-p0006-a1","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"6","seq":102,"section":"Annex I","text":"The Main Directorate for Combatting Organized Crime and Corruption (GUBOPiK)\nis a unit within the Ministry of Internal Affairs. The Third Department, responsible for\ncountering extremism, has three divisions: the first division is responsible for “countering\nextremism in radical public and other formations”; the second division is responsible for\n“countering extremism in ethnic and religious formation and illegal migration”; and the third\ndivision is responsible for computer intelligence.","annex":1},{"id":"a-hrc-49-71-p0007-a1","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"7","seq":103,"section":"Annex I","text":"In August 2020, four so-called “Attack Groups” were created, comprising of\npersonnel from GUBOPiK who were in command and supported by servicemen of the special\noperations forces of the Armed Forces.","annex":1},{"id":"a-hrc-49-71-p0008-a1","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"8","seq":104,"section":"Annex I","text":"The Internal Troops are a paramilitary gendarmerie forces, subordinate to the Ministry\nof Internal Affairs that includes the Minsk-based 3rd Red Banner Separate Special-Purpose\nBrigade (Military 3214 “Uruchenskaya Brigade”), whose Special Rapid Response Unit\n(SOBR) performs crowd control functions as part of the riot police system. The Ministry of\nInternal Affairs has the authority to conduct investigations into alleged misconduct by all\nsubordinate forces.","annex":1},{"id":"a-hrc-49-71-p0009-a1","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"9","seq":105,"section":"Annex I","text":"The Almaz Special Anti-Terrorism Unit (Almaz), a special-purpose detachment of the\nMinistry of Internal Affairs, was also deployed to operationally assist in the dispersal of mass\nprotests.","annex":1},{"id":"a-hrc-49-71-p0010-a1","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"10","seq":106,"section":"Annex I","text":"Alongside the abovementioned Ministry of Internal Affairs bodies, the forces and\nofficials of the Committee for State Security (KGB); the Operations and Analysis Centre\nunder the President; the Investigative Committee; and the Ministry of Defence were involved\nin the events during the 9 to 14 August period.","annex":1},{"id":"a-hrc-49-71-p0011-a1","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"11","seq":107,"section":"Annex I","text":"The Committee for State Security of the Republic of Belarus (KGB) is Belarus’\nnational intelligence agency. The Alpha Group is an elite KGB unit dedicated to anti-\nterrorism operations, that can be tasked to assist operationally the Public Security Police and\nother law enforcement agencies.","annex":1},{"id":"a-hrc-49-71-p0012-a1","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"12","seq":108,"section":"Annex I","text":"The Operations and Analysis Centre under the President of the Republic of Belarus\n(OAC) is the state security agency in charge of classified information and state secrets,\nresponsible for the information environment and telecommunication channels including\ninternet traffic control.","annex":1},{"id":"a-hrc-49-71-p0013-a1","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"13","seq":109,"section":"Annex I","text":"The Investigative Committee, a body nominally independent from the Ministry of\nInternal Affairs, is exercising authority in the area of pre-trial criminal proceedings.","annex":1},{"id":"a-hrc-49-71-p0014-a1","rec_id":"recAPuPpgVIcezr4x","symbol":"A/HRC/49/71","n":"14","seq":110,"section":"Annex I","text":"The Ministry of Defence ordered the transfer of servicemen from the 5th Spetsnaz\nBrigade to assist the Special Purpose Police Department (OMON).","annex":1},{"id":"a-hrc-52-68-u0000","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":null,"seq":0,"section":null,"text":"United Nations                                                                                   A/HRC/52/68\nGeneral Assembly                                                           Distr.: General\n3 February 2023","unnumbered":true},{"id":"a-hrc-52-68-u0001","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":null,"seq":1,"section":null,"text":"Human Rights Council\nFifty-second session\n27 February–31 March 2023\nAgenda items 2 and 4\nAnnual report of the United Nations High Commissioner\nfor Human Rights and reports of the Office of the\nHigh Commissioner and the Secretary-General\nHuman rights situations that require the Council’s attention","unnumbered":true},{"id":"a-hrc-52-68-u0002","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":null,"seq":2,"section":null,"text":"Summary\nIn the present report, submitted pursuant to Human Rights Council resolution 49/26,\nthe High Commissioner sets out the findings of the examination of the human rights situation\nin Belarus since May 2020 and makes recommendations to relevant stakeholders. The report\nincludes updated information on developments and incidents about which OHCHR has\ncollected, consolidated, preserved and analysed information and evidence, with a view to\ncontributing to accountability for perpetrators and justice for victims. He concludes that there\nare sufficient grounds to believe that systematic, widespread and gross human rights\nviolations have been and are being committed in Belarus.","unnumbered":true},{"id":"a-hrc-52-68-u0003","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":null,"seq":3,"section":null,"text":"* Agreement was reached to publish the present report after the standard publication date owing to\ncircumstances beyond the submitter’s control.\n** The annexes to the present report are circulated as received, in the language of submission only.","unnumbered":true},{"id":"a-hrc-52-68-p0001","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"1","seq":4,"section":"I. Introduction","text":"The present report is submitted pursuant to Human Rights Council resolution 49/26,\nin which the Council requested the United Nations High Commissioner for Human Rights to\nmonitor and report on the situation of human rights in Belarus and to examine all alleged\nhuman rights violations committed in Belarus since 1 May 2020, in the run-up to the 2020\npresidential election and in its aftermath."},{"id":"a-hrc-52-68-p0002","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"2","seq":5,"section":"I. Introduction","text":"The present report should be read in conjunction with the previous report of the High\nCommissioner, 1 in which she provided an overview of the situation of human rights in\nBelarus, in particular the period from 9 to 14 August 2020, during and immediately after the\n2020 presidential election."},{"id":"a-hrc-52-68-p0003","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"3","seq":6,"section":"I. Introduction","text":"An examination team of the Office of the United Nations High Commissioner for\nHuman Rights (OHCHR), based in Vienna, supported the High Commissioner in\nimplementation of the mandate. The High Commissioner appointed three experts to assist in\nthe discharge of the mandate: Karinna Moskalenko (Russian Federation), Susan Bazilli\n(Canada) and Monica Płatek (Poland)."},{"id":"a-hrc-52-68-p0004","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"4","seq":7,"section":"II. Methodology and standard of proof","text":"The present report covers the period from 1 May 2020 to 31 December 2022 2 and is\nbased on a detailed analysis of 207 interviews (127 with men, 79 with women and 1 with a\nboy) conducted remotely and in-person with victims and witnesses, representatives of non-\ngovernmental organizations, journalists, lawyers and medical personnel, in addition to\ninterviews conducted during the previous reporting period. 3 OHCHR corroborated\ninformation gathered to ensure its validity, assessed the credibility and reliability of all\nsources, sought informed consent from those sources to use or share material collected and\ntook all appropriate measures to protect confidentiality and ensure the protection of\ninterviewees."},{"id":"a-hrc-52-68-p0005","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"5","seq":8,"section":"II. Methodology and standard of proof","text":"In addition to first-hand statements, OHCHR collected, preserved and analysed more\nthan 2,500 items of information and evidence, including photographs, videos, public\nstatements by officials, reports, copies of original medical records, court documents and other\ndigital data. OHCHR received 16 submissions, from individuals, both victims and witnesses,\nand other stakeholders, such as non-governmental and international organizations, in\nresponse to its call for submissions.4"},{"id":"a-hrc-52-68-p0006","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"6","seq":9,"section":"II. Methodology and standard of proof","text":"OHCHR used “reasonable grounds to believe” as the standard of proof. The standard\nis met when factual information has been collected that would satisfy an objective and\nordinarily prudent observer that the incident has occurred as described, with a reasonable\ndegree of certainty. This standard of proof is lower than that which is required for finding\ncriminal responsibility."},{"id":"a-hrc-52-68-p0007","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"7","seq":10,"section":"II. Methodology and standard of proof","text":"In its resolution 49/26, the Human Rights Council urged the Belarusian authorities to\nrestore their cooperation with and extend full and unhindered access to OHCHR. OHCHR\nregrets that the Government of Belarus has not positively responded to the two notes verbales,\nof 23 August 2022 and 11 November 2022, from OHCHR seeking access to the country and\nenclosing a list of issues."},{"id":"a-hrc-52-68-p0008","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"8","seq":11,"section":"II. Methodology and standard of proof","text":"The High Commissioner extends his gratitude to States Members of the United\nNations, the Special Rapporteur on the situation of human rights in Belarus, the three experts,\nthe Organization for Security and Cooperation in Europe and civil society organizations for\nthe material shared with, and support provided to, it in the discharge of the mandate. OHCHR\nwishes to acknowledge, with profound appreciation, the victims, survivors and witnesses\nwho have shared their experiences and other relevant information."},{"id":"a-hrc-52-68-p0009","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"9","seq":12,"section":"III. Applicable law","text":"OHCHR continued to assess the situation of human rights in the country on the basis\nof applicable international law, including human rights treaties to which Belarus voluntarily\nbecame a State party, as well as customary international law applicable to all States. 5 A\nreview of relevant domestic legislation and legislative changes was also conducted."},{"id":"a-hrc-52-68-p0010","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"10","seq":13,"section":"A. Unnecessary and disproportionate use of force","text":"In the previous report, the High Commissioner found that there had been widespread\nunnecessary and disproportionate use of force, including the use of police batons, tear gas,\nkinetic impact projectiles, stun grenades and water cannons, against peaceful protesters from\n9 to 14 August 2020.6 Additional witness accounts collected by OHCHR further confirmed\nthat such crowd control equipment and weapons were actively used to forcibly disperse\nprotests in Minsk, at least until November 2020. The President of Belarus, Alexandr\nLukashenko, stated, in August and September 2020, that he would not allow street protests. 7\nCredible reports were also received on the unnecessary use of force against peaceful\nprotesters in response to anti-war protests at the time of the constitutional referendum in\nFebruary 2022. In addition to less-lethal weapons, OHCHR gathered information confirming\nthe use of firearms during protests and documented at least two cases in which firearms had\nbeen discharged to stop cars with protesters on the streets of Minsk in August 2020."},{"id":"a-hrc-52-68-p0011","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"11","seq":14,"section":"A. Unnecessary and disproportionate use of force","text":"OHCHR found that, in addition to various units of the Ministry of Internal Affairs and\nthe Committee for State Security, established under and formerly part of the Committee for\nState Security of the Union of Soviet Socialist Republics (KGB), the authorities deployed the\narmed forces, in responding to the protests in 2020. The order was given by Major General\nVadim Denisenko, commander of the special operations forces of the Ministry of Defence. 8\nOn 12 October 2020, Deputy Minister of the Interior, Gennady Kazakevich, stated that law\nenforcement was permitted to “use special equipment and military weapons” against\nprotesters, if needed.9"},{"id":"a-hrc-52-68-p0012","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"12","seq":15,"section":"A. Unnecessary and disproportionate use of force","text":"OHCHR collected and analysed testimonies and information on several cases of\ndeaths that allegedly resulted from unnecessary or disproportionate force used during the\nprotests in 2020 and from a failure to protect life in detention. In at least five cases, OHCHR\nfound reasonable grounds to believe that they were unlawful deprivation of life, 10 either\nresulting from the excessive use of force by law enforcement personnel, which was not\nstrictly necessary in order to protect life or prevent serious injury from an imminent threat,\n5  The applicable legal framework was outlined in the previous report (A/HRC/49/71), paras. 11–15.\n6  A/HRC/49/71, paras. 25–30.\n7 See https://president.gov.by/en/events/soveshchanie-po-obespecheniyu-bezopasnosti-izbiratelnoy-\nkampanii-1596721781#block-after-media-scroll; and https://president.gov.by/en/events/meeting-with-\nbelarusian-high-ranking-officials#block-after-media-scroll.\n8 See https://belsat.eu/ru/news/17-02-2021-sud-po-delu-shutova-stalo-izvestno-kto-prikazal-ispolzovat-\nvooruzhennyh-voennyh-vo-vremya-protestov/; and https://www.svaboda.org/a/31107424.html.\n9 See https://meduza.io/news/2020/10/12/mvd-belorussii-prigrozilo-ispolzovat-ognestrelnoe-oruzhie-\ndlya-razgona-mitingov; and https://www.reuters.com/article/us-belarus-election-protests-arms-\nidUSKBN26X1TT’; and official social media sources (https://t.me/pressmvd/2226’ and\nhttps://www.youtube.com/watch?v=snEieUhSTfU).\n10 Human Rights Committee, general comment No. 36 (2018) on the right to life, paras. 12, 25, 27 and\n29; and general comment No. 37 (2020) on the right of peaceful assembly, paras. 78 and 88; and\nMinnesota Protocol on the Investigation of Potentially Unlawful Death, para. 2.\nor a failure to respect the right to life of a detained person. Both scenarios constitute a\nviolation of the right to life. The cases include the deaths of the following people:\n(a)   Aliaksandr Taraykouski, a 34-year-old man, who was shot in the chest by a\nrubber shotgun slug on 10 August 2020 in the centre of Minsk;\n(b)    Aliaksandr Vikhor, a 25-year-old man, who died in a hospital in Homiel on 12\nAugust 2020, after being arrested on the night of 9 August and ill-treated in detention;\n(c)    Henadz Shutau, a 44-year-old man, who was shot in the head on 11 August\n2020 in Brest and died in a military hospital in Minsk on 19 August;\n(d)     Raman Bandarenka, a 31-year-old man, who was severely beaten and abducted\nby plain-clothes special operations servicemen in Minsk on 11 November 2020 and died in\na hospital on 12 November;\n(e)    Vitold Ashurak, a 50-year-old man, who was an opposition activist, was\nsentenced, on 18 January 2021, to five years’ imprisonment and who died in the penal colony\nin Shklou, Mahilyou region, on 21 May 2021, allegedly as a result of cardiac arrest."},{"id":"a-hrc-52-68-p0013","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"13","seq":16,"section":"A. Unnecessary and disproportionate use of force","text":"The authorities failed to conduct impartial, prompt, effective, and transparent\ninvestigations into any of those deaths.11 Moreover, the authorities deliberately disseminated\nfalse information to the public about the victims and the circumstances surrounding the\ndeaths, 12 denied access for relatives and lawyers to preliminary investigation material, 13\nbrought charges against witnesses, 14 harassed and intimidated the victims’ relatives 15 and\npersecuted journalists and medical professionals who opposed the official narrative. 16 Such\nactions by the authorities are incompatible with the State’s obligations to take appropriate\nmeasures to establish the truth relating to the events leading to the deprivation of life, to\nensure that potential perpetrators are brought to justice and to prevent impunity."},{"id":"a-hrc-52-68-p0014","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"14","seq":17,"section":"A. Unnecessary and disproportionate use of force","text":"OHCHR received allegations17 of a number of other cases of deaths in the context of\nprotests since August 2020. Given the widespread unlawful use of force, the widespread and\nsystematic practice of torture and inhuman treatment, including denial of medical care, and\nthe overall situation of impunity, the actual death toll during the protests and related arrests\nmay have been higher, and further investigation is required."},{"id":"a-hrc-52-68-p0015","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"15","seq":18,"section":"B. Torture and other cruel, inhuman or degrading treatment","text":"In the previous report, the High Commissioner described the widespread and\nsystematic practice of torture and ill-treatment, that was largely punitive in nature, directed\nagainst individuals for their real or perceived opposition to the Government or the election\nresults.18 OHCHR continued documenting multiple cases of torture and other cruel, inhuman\nor degrading treatment or punishment that occurred during the reporting period. Those acts\nwere usually committed after arrest, in police vehicles, police stations or police detention\ncentres. Interviewees provided OHCHR with consistent accounts of torture and ill-treatment\nbeing used during interrogation for punishment purposes and to coerce individuals into\nmaking incriminating confessions or providing information, including mobile phone\npasswords and login credentials."},{"id":"a-hrc-52-68-p0016","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"16","seq":19,"section":"B. Torture and other cruel, inhuman or degrading treatment","text":"OHCHR continued to document that many victims, of all ages, were violently\napprehended and subjected to prolonged beatings in police vehicles with batons, fists and\nfeet. Detainees were hit, punched and kicked in different parts of the body, resulting in head\nconcussions, blood in the urine, kidney and eardrum membrane injuries, hematomas and\nfractures. Some victims were obliged to remain in bed for months, unable to walk, or were\ndiagnosed with closed craniocerebral trauma. Beatings were accompanied by intensive\npsychological violence in the form of death threats, rape threats, sexually abusive comments,\ninsults and other verbal abuse. A forensic analysis undertaken of available medical\ndocuments and images pertaining to the injuries sustained in 2020 were consistent with\nfindings outlined in the previous report. In addition, in a minimum of eight cases, bruises\nmirroring shoe soles were identified on the faces, chests, backs, shoulders and legs of injured\npersons. Some had three or more different shoe marks on their body. OHCHR concludes that\nthese bruises were likely acquired while the persons were on the ground, posing no danger to\nsecurity forces or others, and that, depending on its severity and particular circumstances,\nthey could meet the threshold of torture or other ill-treatment."},{"id":"a-hrc-52-68-p0017","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"17","seq":20,"section":"B. Torture and other cruel, inhuman or degrading treatment","text":"In police stations, in cases documented since May 2020, officers applied various\nmethods of physical violence to detainees, including kicking and beating certain body parts\nwith batons, while the detainees were tightly handcuffed. Police officers made them stand in\ncorridors and courtyards, in stress positions, with legs spread as wide apart as possible, for\nprolonged periods. Officers held detainees face down on the floor, with legs pulled up, and\nwith a rope attached to handcuffs. They deprived them of water and medical care. 19"},{"id":"a-hrc-52-68-p0018","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"18","seq":21,"section":"B. Torture and other cruel, inhuman or degrading treatment","text":"The majority of detainees, mainly men held on politically motivated charges, continue\nto be arrested and detained in two detention facilities, Okrestsina and Zhodzina. OHCHR has\nreasonable grounds to believe that detention conditions in those facilities amounted to cruel,\ninhuman and degrading treatment or, in some cases, torture. Victims reported being kept in\nseverely overcrowded cells, usually exceeding more than twice the designated number of\npersons per cell, and being forced to sleep on concrete floors in lines, without mattresses,\nbedding or ventilation. The guards regularly poured high concentrations of chlorine in the\ncells, making detainees feel sick and unable to breathe. In most cases, detainees had no access\nto basic hygienic items, such as toilet paper, soap, toothbrushes and toothpaste, towels or\nmenstrual hygiene products. Interviewees reported that they were only allowed to sit or lie\ndown while in the cell, between 10 p.m. and 6 a.m., and were otherwise required to stand or\nwalk. All victims interviewed were systematically deprived of sleep for days or weeks, the\nresult of continuous artificial light, unsafe temperatures and overcrowding in cells, forced\nawakening and inspections conducted at night."},{"id":"a-hrc-52-68-p0019","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"19","seq":22,"section":"B. Torture and other cruel, inhuman or degrading treatment","text":"According to credible testimony, guards often behaved aggressively, subjecting\ndetainees to verbal abuse and insults, including of a sexual and gender-based nature. OHCHR\ndocumented several consistent reports of detainees being assaulted and/or tortured with\nbeatings and asphyxiation. In the majority of cases, detainees were not provided with the\nnecessary medical assistance. As a result of such circumstances and detention conditions,\nsome detainees, after their release, developed serious illnesses, including pneumonia,\ninsomnia, mental disorders and chronic kidney disease."},{"id":"a-hrc-52-68-p0020","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"20","seq":23,"section":"B. Torture and other cruel, inhuman or degrading treatment","text":"OHCHR was informed that, in Zhodzina and temporary detention facility No. 1 in\nMinsk, medical checks were performed rarely and, when they were performed, were only\n18   A/HRC/49/71, para. 53.\n19   District police stations under the District Department of Internal Affairs and the Okrestsina and the\nZhodzina temporary detention centres.\nconducted behind the closed prison cell door and through food port windows. Detainees were\nnot allowed to have bedding, receive packages from relatives, use a shower, have dimmed\nlighting at night in cells or exercise outside their cells. Some such detainees were\nintentionally placed in overcrowded or solitary confinement cells, with the aim of inflicting\nadditional physical and emotional pain and suffering. Family visits and correspondence for\nthose convicted in relation to politically motivated charges20 were severely restricted, and\nyellow tags were attached to the clothing and beds of those prisoners."},{"id":"a-hrc-52-68-p0021","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"21","seq":24,"section":"B. Torture and other cruel, inhuman or degrading treatment","text":"The authorities failed to prosecute and punish acts of torture and ill-treatment\ncommitted in the aftermath of the 2020 presidential election and have been unable or\nunwilling to investigate similar allegations since. During the period from 9 to 14 August\n2020, the former Deputy Minister of the Interior, Aleksandr Barsukov, visited Okrestina\ndetention facility at least once, but failed to take action to stop acts of torture and ill-treatment\nof detainees. On the contrary, labelling victims’ accounts as “disinformation”, the\nGovernment initiated criminal investigations against 51 persons who filed complaints\nregarding the treatment they had suffered.21"},{"id":"a-hrc-52-68-p0022","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"22","seq":25,"section":"C. Arbitrary arrest and detention","text":"Regarding the events of 9 to 14 August 2020, additional interviews conducted further\nconfirmed the findings set out in the previous report22 indicating that the mass arrests and\ndetentions were carried out in response to the legitimate exercise of the rights to freedom of\nexpression, peaceful assembly and association. OHCHR found that there are reasonable\ngrounds to believe that arrest and detention was instigated by the authorities to intimidate,\npunish and deter the population from leaving their homes in exercise of their rights, resulting\nin fear and self-censorship. 23 Besides the organizers of the protests and the participants,\nsecurity forces targeted observers and bystanders, with many arrested at random. Some\npeople with certain characteristics, such as long hair on men, a specific hair colour, facial\nhair or tattoos, were targeted. In addition, individuals who spoke the Belarusian language,\nwhich became one of the symbols of the protests, were often associated with the opposition\nmovement and targeted. OHCHR also documented cases of enforced disappearance lasting\nseveral days.24"},{"id":"a-hrc-52-68-p0023","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"23","seq":26,"section":"C. Arbitrary arrest and detention","text":"Arbitrary arrest and detention occurred not only in the immediate aftermath of the\nAugust 2020 election, but also continued thereafter. Several additional waves of arbitrary\narrest and detention were identified, especially of journalists, human rights defenders and\ntrade unions activists. They occurred in December 2020, January and February and July 2021\nand April 2022. The officers conducting the arrests did not identify themselves. Even where\narrest and search warrants were presented, and in most cases documented, those being\narrested were not afforded the opportunity to read them. The officers forced themselves into\nhomes, or used other forms of coercion to enter, and conducted questioning and searches,\ndemanding that mobile phones be unlocked. Computers and other items were seized without\nexplanation."},{"id":"a-hrc-52-68-p0024","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"24","seq":27,"section":"C. Arbitrary arrest and detention","text":"In July 2021, dozens of persons were arrested and charged with displaying symbols,\nsuch as a piece of white paper in their windows, engaging in the work of non-governmental\norganizations or distributing materials labelled as “extremist”. The majority were sentenced\nto 10 to 15 days’ detention. They were threatened and their phones and other items\nconfiscated. Many were subjected to beating, and some to electric shocks. When apartments\nwere searched, it frequently happened without a search warrant and often with the use of\nforce. Interviewees reported not being promptly informed about the reasons for the search,\nseizure of property or arrest."},{"id":"a-hrc-52-68-p0025","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"25","seq":28,"section":"C. Arbitrary arrest and detention","text":"On 27 and 28 February 2022, around 1,500 persons were arbitrarily arrested and\ndetained for taking part in demonstrations related to the 2022 constitutional referendum, and\nfollowing with the armed attack by the Russian Federation against Ukraine, for displaying\nanti-war signs and banners and chanting pro-Ukrainian slogans. Some of those interviewed\nreported having been subjected to beating and threats during arrest and at police stations.\nThey were later charged with violating the procedure for organizing or holding mass events."},{"id":"a-hrc-52-68-p0026","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"26","seq":29,"section":"D. Rights to due process and a fair trial","text":"OHCHR established that violations of the rights to due process and a fair trial in both\nadministrative and criminal proceedings continue to be numerous and systematic in Belarus,\nsince the August 2020 protests. The judiciary in Belarus lacks independence, given the\nPresident’s role in, and control over, the appointment, promotion and dismissal of judges and\nprosecutors.25 Decisions on whether an investigation should be opened and whether a person\nwill be detained, charged and convicted to prison terms are taken exclusively by investigators\nand State security forces, including the Main Directorate for Combating Organized Crime\nand Corruption and the Committee for State Security. The Office of the Prosecutor approved\nsuch decisions in almost all cases, with judges simply implementing the decisions."},{"id":"a-hrc-52-68-p0027","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"27","seq":30,"section":"D. Rights to due process and a fair trial","text":"Individuals appearing before courts were unable to defend themselves effectively or\nthrough legal assistance of their own choosing. Records of administrative offences drafted\nby law enforcement, and reviewed by OHCHR, in many cases were the only documents used\nas evidence and were relied upon by judges at trial, when issuing their decisions, even though\nthey often contained factual or legal errors and false information. Trials in administrative\ncases continued to be conducted online via videoconference, without justification, with\nprosecution evidence being based mostly on the written testimony of police officers who\ncould not be cross-examined or anonymous witnesses whose identity was not disclosed to\nthe defence. The non-disclosure was allegedly to protect prosecution witnesses or for reasons\nof State security. In addition, legal counsel were not able to call or cross examine witnesses\nor present additional evidence and, when presented, it was not duly considered by the court.\nThese elements, taken cumulatively, indicate that the courts do not appear to a reasonable\nobserver to be impartial and that victims of human rights violations are effectively denied\ntheir right to appeal or other remedies.26"},{"id":"a-hrc-52-68-p0028","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"28","seq":31,"section":"D. Rights to due process and a fair trial","text":"The information documented and testimonies gathered for the present report indicate\nthat, in a large number of cases, the right to legal assistance was violated. The interviewees\nwere not given access to legal assistance at various stages of the proceedings, including\nduring the police questioning, some could only communicate with their lawyers online and\nshortly before the trial and the communications were not confidential."},{"id":"a-hrc-52-68-p0029","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"29","seq":32,"section":"D. Rights to due process and a fair trial","text":"Lawyers continue to be subjected to unfair disciplinary proceedings disbarment, and,\nin some cases, arrest, detention and prosecution, merely for performing their professional\nfunctions and duties. Hundreds of lawyers have reportedly left the profession, 27 and, since\nthe 2020 elections, 73 lawyers were deprived from practising through disbarment, revocation\nof licences and prosecution,28 further depriving victims of the right to legal counsel and a fair\nhearing. In May 2022, the Working Group on Arbitrary Detention found that the arrest and\ndetention of Maxim Znak was arbitrary, as it lacked a legal basis, was due to the peaceful\nexercise of his rights, was the result of violations of his fair trial rights and was based on\ndiscrimination on the basis of his political opinion and his status as a lawyer of the political\nopposition movement.29"},{"id":"a-hrc-52-68-p0030","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"30","seq":33,"section":"D. Rights to due process and a fair trial","text":"OHCHR documented disproportionately severe sentences passed by the courts, which\nare further illustrative of the instrumentalization and abuse of the justice system. 30 Such\n25 A/HRC/49/71, para. 89; CCPR/C/BLR/CO/5, para. 39; and A/75/173, paras. 21–22.\n26 A/HRC/49/71, para. 89.\n27 A/HRC/50/58, para. 85.\n28 See https://www.defenders.by/right_to_protection.\n29 A/HRC/WGAD/2022/24.\n30 OHCHR, “UN experts call for immediate release of jailed Nobel winner and other rights defenders in\nBelarus”, press release, 10 October 2022.\nsentences include those handed down against political opposition figures, 31 bloggers, 32\njournalists, 33 human rights defenders 34 and lawyers. 35 In certain circumstances, grossly\ndisproportionate sentencing could itself also amount to prohibited ill-treatment.36"},{"id":"a-hrc-52-68-p0031","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"31","seq":34,"section":"D. Rights to due process and a fair trial","text":"In July 2022, the Criminal Procedure Code was amended to allow for special criminal\nproceedings, conducted in absentia, against persons who are outside Belarus for acts of\nterrorism, treason or sabotage, setting up an extremist organization or participation in it,\nparticipation in mass riots and calling for sanctions. 37 The amendment has been introduced\nto target political activists outside Belarus, punish them for speaking out and, following\nconviction, seize their property on the basis that they are “traitors and extremists”. 38"},{"id":"a-hrc-52-68-p0032","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"32","seq":35,"section":"E. Freedoms of expression, peaceful assembly and association","text":"During the period under review, the authorities continued to target those who\nparticipated in the 2020 mass protests. The authorities made increasing use of digital\nsurveillance, with the creation of a forensic video library containing hundreds of thousands\nof files, leading to the identification of more than 1,400 participants in what the authorities\nreferred to as “street terror”. The authorities also used artificial intelligence to assist in the\nidentification of “extremism” material in Telegram channels. Those identified were detained\nand charged with criminal and administrative offences. The use of facial recognition and\nother mass surveillance technology by the Belarusian authorities in order to potentially\nidentify every participant in a peaceful demonstration, constitutes an interference with the\nright to privacy and has a highly detrimental effect on the enjoyment of other rights, including\nthe rights to freedom of expression and peaceful assembly.39"},{"id":"a-hrc-52-68-p0033","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"33","seq":36,"section":"E. Freedoms of expression, peaceful assembly and association","text":"Cases of public dissent, whether protests on the streets or posting critical content\nonline, have been less frequent, since the end of 2020, as a result of the violent crackdown\nby the authorities, with not a single mass gathering of the opposition and supporters of change\nin Belarus authorized.40 A spike in protests was documented in February and March 2022, in\nthe context of the armed attack by the Russian Federation against Ukraine and the\nconstitutional referendum in Belarus.41 Displays of dissent, including online dissent, related\nto the anti-war movement were considered as extremism. For example, expressing criticism\nof the Russian military or solidarity with Ukrainian citizens was generally classified by law\nenforcement as incitement to national discord.42"},{"id":"a-hrc-52-68-p0034","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"34","seq":37,"section":"E. Freedoms of expression, peaceful assembly and association","text":"As at December 2022, 1,446 persons (1,284 men and 162 women), including 10\nchildren, were detained on what OHCHR has reasonable grounds to believe to be politically\nmotivated charges. The use of terrorism- and extremism-related offences to intimidate,\nrepress and prosecute individuals and organizations exercising their rights to freedom of\nexpression, peaceful assembly and association increased. According to official data, between\nAugust 2020 and July 2022, the authorities initiated more than 11,000 criminal cases relating\nto extremism.43"},{"id":"a-hrc-52-68-p0035","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"35","seq":38,"section":"E. Freedoms of expression, peaceful assembly and association","text":"In July 2021, the President of Belarus announced that the Government had initiated a\nvigorous campaign to crack down on non-governmental organizations and so-called\n“Western mass media”.44 The authorities applied the concept of “extremist formations” to\ntarget hundreds of social media groups and channels and private chats. Most independent\nBelarusian media outlets are considered “extremist” by the authorities, including hundreds\nof social media channels and blogs. OHCHR found that such an expansive concept of\n“extremism” was incompatible with the principle of legality and that domestic extremism\nand counter-terrorism laws were used to suppress dissent. As at November 2022, at least\n1,784 persons had been convicted of crimes that are characterized as grossly violating public\norder, insulting the President or a representative of the authorities or inciting social discord. 45"},{"id":"a-hrc-52-68-p0036","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"36","seq":39,"section":"E. Freedoms of expression, peaceful assembly and association","text":"In September 2020, the President stated that mass media outlets should be agents of\nthe State ideology, and journalists should be “the most ardent supporters of the authorities”.\nHe also maintained that independent outlets and Telegram channels were “spreading fake\nnews destabilizing the country, destroying people’s trust in the Government”. 46 The\nauthorities continued to equate independent journalism with extremism. In 2022, regional\nindependent media outlets were actively targeted, along with the remaining nationwide ones,\nsuch as Nasha Niva, and foreign media outlets Euroradio and Charter’97. Since May 2020,\nthe authorities have conducted 199 raids of homes and offices, arresting 625 journalists and\nmedia workers. The courts passed verdicts in many cases, and, as at December 2022, 32\njournalists and media workers remained in detention, frequently serving long prison\nsentences."},{"id":"a-hrc-52-68-p0037","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"37","seq":40,"section":"E. Freedoms of expression, peaceful assembly and association","text":"By December 2022, the number of liquidated non-governmental organizations\nreached 757, and 416 organizations made the difficult decision to close in order to avoid\npotential criminal prosecution. These statistics include virtually all human rights groups\nworking in the country. Since January 2022, an amendment47 to the Criminal Code provides\nthat a person taking part in activities of an unregistered organization or one that has been\nliquidated, faces a sentence of two years’ imprisonment. The provision is aimed at\nintimidating civil society and has a chilling effect on civic space and the exercise of\nfundamental freedoms. 48 In June and November 2022, the prosecutor’s office in Grodno\nlaunched the first two investigations under the amendment.49"},{"id":"a-hrc-52-68-p0038","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"38","seq":41,"section":"E. Freedoms of expression, peaceful assembly and association","text":"The authorities conducted numerous searches of trade union premises and the homes\nof trade union leaders and activists across Belarus. On 19 April 2022, at least 23 trade union\nleaders and activists were detained. The International Labour Organization called for the\nrelease of trade union leaders and for an end to intimidation of those exercising the right to\nsolidarity with Ukrainian victims on social media platforms or for playing a Ukrainian song. See\nhttps://prisoners.spring96.org/en/table-convicted.\n43 See https://sk.gov.by/ru/news-ru/view/v-sledstvennom-komitete-podveli-itogi-raboty-za-pervoe-\npolugodie-11675/.\n44 See https://president.gov.by/en/events/rabochiy-vizit-v-rossiyskuyu-federaciyu-1626158209#block-\nafter-media-scroll.\n45 See https://www.mvd.gov.by/ru/news/9186.\n46 See https://president.gov.by/en/events/meeting-with-belarusian-high-ranking-officials#block-after-\nmedia-scroll.\n47 Criminal Code of Belarus, art. 193.\n48 A/HRC/50/58, para. 28; and CCPR/C/BLR/CO/5, paras. 54–55. See also Criminal Code of Belarus,\nart. 193.\n49 See https://www.prokuratura.gov.by/ru/media/novosti/nadzor-za-resheniyami-po-ugolovnym-i-\ngrazhdanskim-delam/prodolzhali-rabotat-nesmotrya-na-reshenie-suda-o-likvidatsii-obedineniya-\nprokuratura-grodnenskoy-obl/; and https://prokuratura.gov.by/ru/media/novosti/nadzor-za-\nresheniyami-po-ugolovnym-i-grazhdanskim-delam/nezakonno-organizova/.\nfreedom of association.50 In July 2022, the Supreme Court dissolved the Belarusian Congress\nof Democratic Trade Unions, along with its four member organizations, for engaging in\npublic affairs, and thereby allegedly exceeding their mandates, effectively quashing the\nindependent trade union movement in the country. As at October 2022, 19 trade union\nactivists remained in detention."},{"id":"a-hrc-52-68-p0039","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"39","seq":42,"section":"F. Sexual and gender-based violence","text":"During the period under review, OHCHR documented over 100 cases of sexual and\ngender-based violence (involving 4 boys, 36 women and 60 men) and reviewed over 180\nadditional cases documented by reputable civil society organizations, whose analysis\nOHCHR found to be credible. The vast majority of the cases pertain to the August 2020\nevents. It does not fully reflect the scale of the sexual and gender-based violations and abuses\ncommitted in Belarus, which is likely to be underreported, owing to stigma, fear of reprisals\nand denial of access to the country. OHCHR documented nine cases involving the targeting\nof male victims’ genitals by the anti-riot police when attacking peaceful protesters, using\nbatons, stun guns and other weapons, as well as detained persons in police vans, police\nstations and detention facilities, and found an additional six cases documented and analysed\nby civil society organizations to be credible. Medical records analysed by OHCHR\ndocumented traumatic injuries to male genitalia, including lesions, multiple abrasions and\ncontusions. Two women told OHCHR that they had been hit in the stomach, requiring one to\nhave lifesaving surgery and subsequently her pregnancy terminated as a result."},{"id":"a-hrc-52-68-p0040","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"40","seq":43,"section":"F. Sexual and gender-based violence","text":"OHCHR documented 27 cases of women who were subjected to unwanted sexual\ncomments and hate speech and received information on an additional 5 cases documented\nand analysed by civil society organizations to be credible. Although women were less likely\nto be beaten after an arrest than male detainees, OHCHR notes that the pattern of physical\nviolence towards female detainees on the basis of unequal power relations, and aiming to\nreinforce women’s’ perceived subordinate status, persisted, even after the most violent period\nof August 2020. When beating women, officers threatened to gang rape them and bragged\nabout having carte blanche for such conduct. Women reported being forced to witness sexual\nand gender-based violence perpetrated against husbands, partners, other men and women,\nwhich is per se a form of sexual violence and intimidation."},{"id":"a-hrc-52-68-p0041","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"41","seq":44,"section":"F. Sexual and gender-based violence","text":"The majority of victims of arbitrary detention who were interviewed by OHCHR\nreported being subjected to strip searches and cavity searches, which were performed\narbitrarily, sometimes several times a day, in a degrading manner, at times in the presence of\nother detainees and staff and not always by persons of the same gender. Women who had\nbeen menstruating at the time of arrest remarked that squatting or bending over while being\nnaked was particularly humiliating. OHCHR documented forced nudity in 40 cases and found\nan additional 137 cases, including but not limited to strip searches, documented and analysed\nby civil society organizations to be credible. Such cases included detainees being naked\nduring transfers between sections of prison facilities and, in some cases, even while appearing\nbefore a judge. OHCHR documented allegations of male prison guards observing women\nchanging clothes and using toilets, shower facilities and dressing rooms, as well as\nmonitoring closed circuit television (CCTV) camera feeds from prison cells, potentially in\nviolation of international standards.51"},{"id":"a-hrc-52-68-p0042","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"42","seq":45,"section":"F. Sexual and gender-based violence","text":"Law enforcement officers and guards used sexual and gender-based violence to\narbitrarily punish those not fitting their perceptions of heteronormativity. People with\ncoloured hair, men and boys with long hair, girls and women with short hair, non-binary\npersons, people with dreadlocks or tattoos and those with “pride” symbols were especially\ntargeted."},{"id":"a-hrc-52-68-p0043","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"43","seq":46,"section":"F. Sexual and gender-based violence","text":"OHCHR documented six cases of rape committed in police vehicles and in police\nstations throughout Minsk against four men and two boys. In one case, a man was raped in\nOkrestino detention centre, following the use of homophobic slurs and death threats. Using\na baton, officers ruptured the victim’s rectum, causing heavy bleeding, and were laughing at\nhim instead of providing first aid, covering his mouth as he was screaming from the\nexcruciating pain. In another case, security officials, while beating a 16-year-old boy in a\npolice van and pressuring him to self-incriminate, inserted a stun gun into his mouth and later\nin a police station a police baton into his mouth, badly injuring the victim, resulting in his\nbeing sent for intensive care hospitalization. OHCHR analysed medical records in other cases\ndetailing injuries, including those from anal penetration. OHCHR is currently investigating\nother alleged cases of rape perpetrated against men and women."},{"id":"a-hrc-52-68-p0044","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"44","seq":47,"section":"F. Sexual and gender-based violence","text":"OHCHR documented 20 rape attempts and found an additional eight cases\ndocumented and analysed by civil society organizations to be credible. The cases were\ncommitted in towns and cities across Belarus, perpetrated against both male and female\nvictims; cases included reports where security officers pulled down, tore or cut the back of\nthe victims’ lower garments, sometimes putting condoms on police batons, and pressing the\nbatons against victims’ anuses."},{"id":"a-hrc-52-68-p0045","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"45","seq":48,"section":"F. Sexual and gender-based violence","text":"OHCHR documented 44 cases of rape threats, affecting over 12 women and almost\n30 men and found an additional 30 cases documented and analysed by civil society\norganizations to be credible. An additional four cases documented by OHCHR involved rape\nthreats directed at victim’s partners. Some detainees were threatened by security officials or\nprison guards to be placed in special cells, with implicit or explicit threats of rape by other\ndetainees. Some law enforcement officers and guards at detention facilities threatened to\nurinate on detainees."},{"id":"a-hrc-52-68-p0046","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"46","seq":49,"section":"F. Sexual and gender-based violence","text":"Sexual and gender-based violence was often directed by men towards men. Victims\ninterviewed by OHCHR noted that rape and other forms of such violence was most often\ncommitted by higher-ranking officers or those in command or under their supervision. Sexual\nand gender-based violence towards men was also committed by female officers. Multiple\nvictims identified a female police officer at one police department who was particularly cruel\nand was described as fixated on sexual sadism."},{"id":"a-hrc-52-68-p0047","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"47","seq":50,"section":"F. Sexual and gender-based violence","text":"OHCHR documented multiple cases in which the authorities either publicly outed or\nused hate speech towards detained lesbian, gay, bisexual, transgender and intersex persons\nin order to punish, humiliate or intimidate them and to deter others. This became a clear\npattern after September 2021, as security services started regularly releasing confession\nvideos revealing detainees’ sexual orientation. The Head of the Main Directorate for\nCombating Organized Crime and Corruption linked support of the opposition with the\nsupport of “LGBT values” and called all such persons “scum of society”. 52 Such actions and\nstatements expose lesbian, gay, bisexual, transgender and intersex persons to life-threatening\nrisks in the prison system, in violation of the authorities’ obligation to ensure the safety and\nwell-being of detainees."},{"id":"a-hrc-52-68-p0048","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"48","seq":51,"section":"G. Child separation and undue interference in family life","text":"OHCHR documented cases of child separation, whereby authorities pressured those\nperceived as opposition supporters to self-incriminate or cooperate with the security forces.\nDozens of interviewees, the majority of them women, indicated that law enforcement\nagencies had resorted to threats of child removal to State-run foster care during house\nsearches, arrests and interrogations, which often prompted them subsequently to relocate or\ngo into exile. Such threats were sometimes accompanied by violence in the presence of, or\ndirected against, children or neglect by law enforcement officers. According to a recent\nconstitutional amendment, children may be separated from their family if their parents fail to\nfulfil their duties, including to “instil in them a culture of respect for the historical and\nnational traditions of Belarus”.53 In this context, separations, threats of separation and the\nimplementation of the constitutional amendment on punitive bases are inconsistent with the\n52 See https://mlyn.by/23112021/nachalnik-gubopik-andrej-parshin-predateli-dolzhnyi-byit-nakazanyi-i-\neto-vopros-vremen/.\n53 Article 32 of the Constitution of Belarus.\nrights to privacy and family life, including the right of the child to family life, enshrined in\narticles 3 (1), 9 and 16 of the Convention on the Rights of the Child."},{"id":"a-hrc-52-68-p0049","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"49","seq":52,"section":"H. Forced exile","text":"OHCHR documented at least seven cases of the forced exile of Belarusian citizens\nand one attempted case of forced exile of a citizen, transported or escorted to the border by\nthe authorities and threatened with arrest if the person did not leave the country. Such\nexpulsions amount to a violation of the rights to liberty of movement and not to be arbitrarily\ndeprived of the right to enter one’s country, enshrined in article 12 (1) and (4) of the\nInternational Covenant on Civil and Political Rights."},{"id":"a-hrc-52-68-p0050","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"50","seq":53,"section":"H. Forced exile","text":"In addition, at least 100,000 individuals have sought safety abroad after the 2020\npresidential election in Belarus.54 Individuals were compelled to leave the country and were\nunable to safely return, owing to the threat of arbitrary detention, ill-treatment in detention\nand unfair trial, as well as violations of economic, social and cultural rights. Such\ndisplacement is directly connected to policies and practices employed by the Government of\nBelarus, including the massive crackdown on dissent and the purposefully hostile\nenvironment that prevents safe return.55"},{"id":"a-hrc-52-68-p0051","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"51","seq":54,"section":"V. Constitutional reform","text":"Constitutional amendments introduced in 2022 include the possibility of termination\nof citizenship.56 In December 2022, legislation was adopted by the parliament, enabling the\nrevocation of citizenship of a person convicted of “participation in extremist activities or\ncausing serious harm to the interests of the Republic of Belarus”, 57 which includes calling for\nsanctions, insulting the President, participating in mass riots or causing damage to public\nproperty. Thousands of Belarusians have already been charged with such offences, and, since\nJuly 2022, can also be tried in absentia. Public statements by the President and the Minister\nof the Interior confirm that the law is directed at those who have “fled and are harming the\ncountry”.58"},{"id":"a-hrc-52-68-p0052","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"52","seq":55,"section":"V. Constitutional reform","text":"The Constitution retains the death penalty, widening the scope of the Criminal Code\nto broadly defined acts of terrorism involving the attempted murder of government officials\nor public figures.59 Consequently, the death penalty may now be imposed for crimes not\ninvolving intentional killing, contrary to international minimum standards on the use of the\ndeath penalty, which limit it to the most serious crimes, involving intentional killing. 60"},{"id":"a-hrc-52-68-p0053","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"53","seq":56,"section":"VI. Conclusions under applicable international law","text":"The collected information confirms the scale and patterns of the violations identified\nin the previous reports of the High Commissioner, 61 as well as their widespread and\nsystematic nature. In the light of the foregoing information set out in the present report, The\nHigh Commissioner has reasonable grounds to believe that several violations of international\nhuman rights law were committed in Belarus between 1 May 2020 and 31 December 2022.\nThey include arbitrary deprivation of the right to life and to liberty, torture and ill-treatment,\nincluding sexual violence, denial of the rights to due process and to a fair trial, arbitrary denial\nof the right to enter one’s own country, violations of the rights to freedom of expression,\npeaceful assembly and association and to equal protection of the law."},{"id":"a-hrc-52-68-p0054","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"54","seq":57,"section":"VI. Conclusions under applicable international law","text":"Some of the violations may also amount to crimes against humanity, as defined in\ninternational customary law, when such acts are committed as part of a widespread or\nsystematic attack directed against any civilian population, with knowledge of the attack.62\nConsidered cumulatively, the organized nature of the violations renders it improbable that\nthey were random and accidental. On the contrary, they appear to have been part of a\ncampaign of violence and repression, intentionally directed at those who were – or were\nperceived to be – opposing the Government or expressing critical or independent voices, a\ncampaign which consisted of the following components:\n(a)     Between 9 and 14 August 2020, thousands of peaceful protesters and those\nperceived as opposition activists were unlawfully beaten with batons by the security forces\nacross Belarus and at least dozens were targeted with rubber bullets and stun grenades; 63 the\nuse of force was approved at a high level within the Government and was highly\ncoordinated;64\n(b)    Tens of thousands have been arrested since May 2020 for legitimately\nexercising their rights to freedom of opinion and expression, peaceful assembly and\nassociation; owing to the dedication of resources and close cooperation between law\nenforcement agencies, State prosecution and the judiciary, thousands were subsequently\ndetained on what appears to be artificial and politically motivated charges; notably, between\n9 August 2020 and 1 July 2022, more than 11,000 criminal cases were opened related to\n“extremism”;65 as at December 2022, tens of thousands have been denied their right to a fair\nhearing by a competent and impartial tribunal;\n(c)     Thousands of complaints concerning torture and ill-treatment were submitted\nby victims to the Investigative Committee of Belarus in 2020, and later dismissed; OHCHR\ndocumented dozens of first-hand accounts of torture and found hundreds of complaints to be\ncredible;66\n(d)    Since August 2020, hundreds of thousands were arbitrarily denied the rights to\npeaceful assembly, association and freedom of expression; more than a dozen legislative\namendments were promoted, since 2021, targeting political activists or those perceived as\nbeing in opposition to the Government; the President has repeatedly used incitement against\nthat group, publicly referring to its members as “rioters”, “scoundrels”, “criminals”, “foreign\nagents”, “traitors”, “rebels”, “enemies”, “extremists”, “ulcers and tumours in the society” and\n“conspirators” and insinuating that they were involved in terrorism and the glorification of\nNazism;67 by the end of 2022, at least 870 Telegram resources and 42 media outlets had been\ndeclared “extremist”, 199 raids had been made on offices and journalists’ homes and 625\njournalists had been detained; 68 between August 2020 and December 2022, over 757\norganizations were or were in the process of dissolution by the authorities, including virtually\nall human rights groups working in the country; thousands were denied the right to work on\npolitical grounds."},{"id":"a-hrc-52-68-p0055","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"55","seq":58,"section":"VI. Conclusions under applicable international law","text":"During the reporting period, the Belarusian authorities failed to carry out prompt,\neffective, thorough, independent, impartial and transparent investigations into those gross\n62 A/HRC/49/71, paras. 84 and 86.\n63 Ibid., paras. 28–30.\n64 Ibid., para. 34.\n65 Acting High Commissioner’s interim oral update on Belarus, 23 September 2022.\n66 A/HRC/49/71, paras. 50–51.\n67 See https://president.gov.by/en/media, August 2020–December 2022.\n68 A/HRC/49/71, para. 70.\nhuman rights violations and possible international crimes, prosecute those allegedly\nresponsible and provide effective remedies to victims, including adequate reparation. 69"},{"id":"a-hrc-52-68-p0056","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"56","seq":59,"section":"VI. Conclusions under applicable international law","text":"OHCHR collected information regarding individuals allegedly involved in the\nperpetration of those gross human rights violations and possible international crimes, at\nvarious levels of the chain of command, including at senior political and command levels."},{"id":"a-hrc-52-68-p0057","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"57","seq":60,"section":"VII. Accountability","text":"In the previous report, the High Commissioner concluded that there was no reasonable\nexpectation for justice to be delivered for human rights violations committed in Belarus and\npointed out that, besides the lack of investigation, there was an active policy to shield\nperpetrators and prevent accountability.70 Furthermore, OHCHR confirms those conclusions.\nOne prominent example concerns law enforcement personnel wearing balaclavas while\nforcibly dispersing peaceful protesters, conducting arbitrary arrests and house searches and\nmistreating detainees. This common practice appears to be aimed at granting impunity,\nassuming that the persons involved cannot be identified.71 A similar “shielding” measure is\nthe ban on independent real-time reporting from those events and locations, 72 thereby\nallowing unrestrained use of force and impeding accountability."},{"id":"a-hrc-52-68-p0058","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"58","seq":61,"section":"VII. Accountability","text":"On various occasions, the President praised the response of law enforcement officials\nto the protests. He emphasized that they acted appropriately to save the country from\ndestruction and that they were protected by the State. An April 2021 amendment to the Law\non the Internal Affairs Bodies of the Republic of Belarus absolved law enforcement officials\nfrom any responsibility for the harm caused as a result of the use of force if carried out in\naccordance with that Law. It authorizes the use of firearms in cases of danger to “health” and\n“in other cases determined by the President”, without clearly restricting the use of lethal force\nto extreme circumstances of imminent threat of death or serious injury. Moreover,\ninternational standards require that cases of injury or death caused by law enforcement\nofficials be promptly investigated and that arbitrary, unlawful or disproportionate use of force\nbe prosecuted and punished as a criminal offence. Noting the Investigative Committee’s\nannouncement that “no cases of unlawful acts by the police had been identified”, OHCHR is\nnot aware of any positive measures taken by the Belarusian authorities to comply with those\naccountability standards during the period under review."},{"id":"a-hrc-52-68-p0059","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"59","seq":62,"section":"VII. Accountability","text":"Under the amended Constitution, immunity is granted to the President for acts\ncommitted in connection with the exercise of presidential powers, even after leaving the\nposition, which further diminishes the prospects of accountability in Belarus, where the\njudiciary and prosecution systems are already controlled by the President. 73"},{"id":"a-hrc-52-68-p0060","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"60","seq":63,"section":"VII. Accountability","text":"The number of competent lawyers who are able and willing to assist victims of human\nrights violations was already extremely low in Belarus, with approximately one lawyer for\n5,000 persons,74 and has further decreased as a result of ongoing harassment and disbarment."},{"id":"a-hrc-52-68-p0061","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"61","seq":64,"section":"VII. Accountability","text":"With regard to accountability avenues outside Belarus, on 8 November 2022, Belarus\ndenounced the Optional Protocol to the International Covenant on Civil and Political Rights,\nthereby withdrawing from the individual complaint procedure and preventing the Human\nRights Committee from receiving individual complaints, despite article 61 of the\nConstitution, which allows for such applications.75"},{"id":"a-hrc-52-68-p0062","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"62","seq":65,"section":"VII. Accountability","text":"Through interviews conducted in 2022, OHCHR sought the views of victims to\nexplore potential avenues for accountability, access to justice and reparations. Victims\nexpressed a range of different possible avenues, such as a referral of the situation in Belarus\nto the International Criminal Court, the establishment of an international tribunal to try those\ninvolved in gross human rights violations, the initiation by Member States of criminal\nproceedings and the expansion of targeted sanctions against those involved in gross human\nrights violations. Many victims expressed deep distrust of national courts, identifying judges\nas the enablers of repression. Others emphasized the need for the dissolution of State entities\ninvolved in violence and repression and for far-reaching institutional reforms. Victims also\nhighlighted the importance of documenting violations and of collecting and preserving\nevidence, which were essential for accountability processes, in the context of future\nrecognition of their status as victims. They expressed the desire that the Government\nacknowledge that their detention and criminal charges were arbitrary and that confessions\nobtained under duress had no validity. That applies also to restoring their dignity, clearing\nany criminal records and restoring the reputation of organizations which have been liquidated\nby the Government. Others mentioned the expectation of reimbursement, including by filing\ncivil lawsuits where possible, for fines that they were obliged to pay following an unfair\nhearing and for losses incurred as a result of confiscated property, loss of work or payment\nof tuition fees without attending school. Some expressed a fear of reprisals against them or\ntheir families and raised the need for visa support to leave Belarus. The need to support\nvictims, including those who had fled the country, with legal assistance, medical care,\npsychosocial support, civil documentation and livelihoods was also highlighted."},{"id":"a-hrc-52-68-p0063","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"63","seq":66,"section":"VII. Accountability","text":"OHCHR is aware of efforts to initiate relevant criminal proceedings in at least six\nnational jurisdictions outside Belarus, on the basis of the principles of universal or\nextraterritorial jurisdiction. It is vital that efforts to collect, document and preserve evidence\nof the violations continue, with a view to assisting future accountability processes."},{"id":"a-hrc-52-68-p0064","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"64","seq":67,"section":"VII. Accountability","text":"OHCHR continued to collect and preserve evidence, with a view to assisting future\naccountability processes. In addition, it has compiled files on individuals and entities that it\nhas reasonable grounds to believe bear responsibility for gross human rights violations,\nincluding those which may amount to crimes under international law. The files include\nreferences to relevant security and civilian structures and a summary of evidence relating to\nthe potential suspect or suspects."},{"id":"a-hrc-52-68-p0065","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"65","seq":68,"section":"VIII. Recommendations","text":"The High Commissioner reiterates the previous 44 recommendations contained\nin the previous reports on Belarus.76"},{"id":"a-hrc-52-68-p0066","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"66","seq":69,"section":"VIII. Recommendations","text":"The High Commissioner recommends that the Government of Belarus:\n(a)    Immediately release all individuals who are arbitrarily detained and\nsentenced on political grounds, ensuring the right to remedies and reparation, and cease\nall other ongoing violations of human rights identified in the present report, including\nthe systematic repression of civil society, independent media and opposition groups and\nindividuals, and refrain from committing such violations in the future;\n(b)    Promptly initiate independent, impartial, effective and transparent\ninvestigations into all past violations of human rights, in particular those that can be\nqualified as crimes under international law, including mass arbitrary arrest and\n75 See https://www.ohchr.org/en/press-releases/2022/11/belarus-withdrawal-individual-complaints-\nprocedure-serious-setback-human.\n76 A/HRC/46/4, paras. 77–83; and A/HRC/49/71, paras. 93–95.\ndetention, torture and other ill-treatment, sexual and gender-based violence, enforced\ndisappearance, and into the gender dimension of any such crimes, and ensure that\ninvestigations address the full chain of command relevant to individual criminal\nresponsibility;\n(c)     Re-accede to the Optional Protocol to the International Covenant on Civil\nand Political Rights;\n(d)  Seek technical assistance from OHCHR to implement the present\nrecommendations."},{"id":"a-hrc-52-68-p0067","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"67","seq":70,"section":"VIII. Recommendations","text":"The High Commissioner recommends that Member States:\n(a)    Work towards accountability through national proceedings based on\naccepted principles of extraterritorial and universal jurisdiction, as relevant and in\naccordance with international law, and, in parallel, explore further targeted measures\nagainst alleged perpetrators of grave human rights violations and abuses, while\nensuring that such measures are imposed for no longer than necessary, are proportional\nand are subject to appropriate human rights safeguards, including human rights\nimpact assessments and monitoring conducted by independent experts;\n(b)   Provide additional protection measures, where necessary, to protect\nvictims, witnesses and other persons who have had to leave the country or who were\nexpelled and those cooperating with investigative bodies in the context of promoting\naccountability and access to justice in Belarus;\n(c)    Maintain the human rights situation in Belarus under review of the\nHuman Rights Council and consider, as appropriate, other accountability mechanisms\nconsistent with the Council’s practice."},{"id":"a-hrc-52-68-p0001-a1","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"1","seq":71,"section":"Annex I","text":"The Office of the United Nations High Commissioner for Human Rights (OHCHR)\npresents its compliments to the Permanent Mission of the Republic of Belarus to the United\nNations Office and other international organizations in Geneva, and wishes to make reference\nto resolution A/HRC/RES/49/26 of the UN Human Rights Council entitled “Situation of\nhuman rights in Belarus in the run-up to the 2020 presidential election and in its aftermath”.","annex":1},{"id":"a-hrc-52-68-p0002-a1","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"2","seq":72,"section":"Annex I","text":"The above-mentioned resolution, inter alia, requests the High Commissioner “to\ncontinue to monitor and report on the situation of human rights, [and] to carry out a\ncomprehensive examination of all alleged human rights violations committed in Belarus\nsince 1 May 2020 in the run-up to the 2020 presidential election and in its aftermath.”","annex":1},{"id":"a-hrc-52-68-p0003-a1","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"3","seq":73,"section":"Annex I","text":"In the context of the implementation of the above-mentioned resolution, OHCHR has\nthe honour to request unhindered access for its monitoring mission to the territory of the\ncountry. OHCHR stands ready to discuss with the Permanent Mission of the Republic of\nBelarus relevant practical arrangements and details for the mission.","annex":1},{"id":"a-hrc-52-68-p0004-a1","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"4","seq":74,"section":"Annex I","text":"The Office of the United Nations High Commissioner for Human Rights avails itself\nof the opportunity to renew to the Permanent Mission of the Republic of Belarus to the United\nNations Office and other international organizations in Geneva the assurances of its highest\nconsideration.","annex":1},{"id":"a-hrc-52-68-p0001-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"1","seq":75,"section":"Annex II","text":"The Office of the United Nations High Commissioner for Human Rights (OHCHR)\npresents its compliments to the Permanent Mission of the Republic of Belarus to the United\nNations Office and other international organizations in Geneva, and wishes to make reference\nto resolution A/HRC/RES/49/26 of the UN Human Rights Council entitled “Situation of\nhuman rights in Belarus in the run-up to the 2020 presidential election and in its aftermath”.","annex":2},{"id":"a-hrc-52-68-p0002-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"2","seq":76,"section":"Annex II","text":"The above-mentioned resolution, inter alia, requests the High Commissioner to\n“continue to monitor and report on the situation of human rights, [and] to carry out a\ncomprehensive examination of all alleged human rights violations committed in Belarus\nsince 1 May 2020 in the run-up to the 2020 presidential election and in its aftermath,\nincluding the possible gender dimensions of such violations, to establish the facts and\ncircumstances surrounding the alleged violations […]; make general recommendations on\nimproving respect for and the protection of human rights; provide guidance on access to\njustice, including reparations, and accountability, as appropriate; and engage with the\nBelarusian authorities and all stakeholders”.","annex":2},{"id":"a-hrc-52-68-p0003-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"3","seq":77,"section":"Annex II","text":"In the context of the implementation of the above-mentioned resolution, OHCHR\nrequested, on 23 August 2022, unhindered access for its monitoring mission to the territory\nof the country.","annex":2},{"id":"a-hrc-52-68-p0004-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"4","seq":78,"section":"Annex II","text":"As of 11 November 2022, OHCHR has not yet received permission from the\nGovernment of Belarus to visit the country. The inability to visit Belarus seriously curtails\nthe Office’s ability to fully execute its mandate in good faith.","annex":2},{"id":"a-hrc-52-68-p0005-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"5","seq":79,"section":"Annex II","text":"Considering the lack of OHCHR’s access to Belarus, the Office prepared the below\nlist of issues pertaining to the Government.","annex":2},{"id":"a-hrc-52-68-p0006-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"6","seq":80,"section":"Annex II","text":"OHCHR respectfully requests the Government to address the queries detailed herein.\nOHCHR will take into account the response of the Government when drafting the next report\nto the Human Rights Council and may add this Note Verbale and the response of the\nGovernment as an annex to the report.","annex":2},{"id":"a-hrc-52-68-p0007-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"7","seq":81,"section":"Annex II","text":"OHCHR would be grateful to receive replies and any other submissions that the\nGovernment may wish to present, no later than 2 December 2022.","annex":2},{"id":"a-hrc-52-68-p0008-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"8","seq":82,"section":"A. Investigations and criminal proceedings","text":"Please provide information on the number of complaints received since May 2020\ninto human rights violations, allegedly committed by law enforcement personnel, which have\nbeen promptly and effectively investigated by the competent authorities, if any and the\noutcome of those investigations.","annex":2},{"id":"a-hrc-52-68-p0009-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"9","seq":83,"section":"A. Investigations and criminal proceedings","text":"Please provide details of remedies provided to victims of human rights violations\nsince May 2020 if any, including reparations.","annex":2},{"id":"a-hrc-52-68-p0010-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"10","seq":84,"section":"A. Investigations and criminal proceedings","text":"Please outline action taken against perpetrators of human rights violations, including\nprosecutions and convictions if any.","annex":2},{"id":"a-hrc-52-68-p0011-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"11","seq":85,"section":"A. Investigations and criminal proceedings","text":"Please provide an update on the total number of persons investigated and prosecuted\nunder extremism- and terrorism-related offences in 2022.","annex":2},{"id":"a-hrc-52-68-p0012-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"12","seq":86,"section":"A. Investigations and criminal proceedings","text":"Please provide an update on the total number of arrests and prosecutions under Art.\n24.23 of the Code of Administrative Offences for participation in unauthorized mass events\nin 2022.","annex":2},{"id":"a-hrc-52-68-p0013-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"13","seq":87,"section":"A. Investigations and criminal proceedings","text":"Please provide information on the total number of arrests and prosecutions in 2022\nunder Article 193-1 of the Criminal Code (participation in the activities of non-registered,\nsuspended or liquidated association).","annex":2},{"id":"a-hrc-52-68-p0014-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"14","seq":88,"section":"A. Investigations and criminal proceedings","text":"Please provide details on the total number of persons charged and prosecuted since\nMay 2020 for insulting the President, a judge or representative of the authorities, as well as\non the criminal or administrative sanction imposed.","annex":2},{"id":"a-hrc-52-68-p0015-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"15","seq":89,"section":"A. Investigations and criminal proceedings","text":"Please provide an update on the total number of “special criminal proceedings” (in\nabsentia) conducted under Chapter 49 of the Criminal Procedural Code.","annex":2},{"id":"a-hrc-52-68-p0016-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"16","seq":90,"section":"B. Policies and procedures","text":"Please provide details on the procedure for approving a “mass event”, and on the\nnumber of approved or rejected requests to hold such a “mass event” since January 2022.","annex":2},{"id":"a-hrc-52-68-p0017-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"17","seq":91,"section":"B. Policies and procedures","text":"Please clarify if there is a specified procedure for handling persons who are detained\nand charged, based on political affiliation or political activities, while they are in detention\nor serving a sentence of imprisonment.","annex":2},{"id":"a-hrc-52-68-p0018-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"18","seq":92,"section":"B. Policies and procedures","text":"Please provide details on the practice of strip search while in detention, including the\ngrounds for conducting such searches.","annex":2},{"id":"a-hrc-52-68-p0019-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"19","seq":93,"section":"B. Policies and procedures","text":"Please outline what rules of engagement on the use of force by law enforcement\nofficials applied during the 2020 protests and thereafter, in relation to crowd control\noperations.","annex":2},{"id":"a-hrc-52-68-p0020-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"20","seq":94,"section":"B. Policies and procedures","text":"Please, outline the legal grounds for involving military personnel in crowd control\noperations during the protests in 2020.","annex":2},{"id":"a-hrc-52-68-p0021-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"21","seq":95,"section":"C. Freedom of expression and association","text":"Please provide an update on the total number of civil society, non-governmental\norganizations and trade unions registered in Belarus since May 2020.","annex":2},{"id":"a-hrc-52-68-p0022-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"22","seq":96,"section":"C. Freedom of expression and association","text":"Please provide an update on the total number of civil society, non-governmental\norganizations and trade unions closed down by the Belarus authorities since May 2020,\nincluding details on the basis for closure.","annex":2},{"id":"a-hrc-52-68-p0023-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"23","seq":97,"section":"C. Freedom of expression and association","text":"Please provide information on the total number of media outlets and telegram channels\nthat have been included in the Republican lists of extremist materials or extremist formations\nsince May 2020.","annex":2},{"id":"a-hrc-52-68-p0024-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"24","seq":98,"section":"C. Freedom of expression and association","text":"Please provide an update on the total number of websites blocked, pursuant to\ndecisions of the Belarus authorities since May 2020.","annex":2},{"id":"a-hrc-52-68-p0025-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"25","seq":99,"section":"D. Due process and the right to a fair trial","text":"Please provide details on how the right to counsel is guaranteed in proceedings under\nthe Code of Administrative Offenses, as well as in disciplinary proceedings against persons\nin custody.","annex":2},{"id":"a-hrc-52-68-p0026-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"26","seq":100,"section":"D. Due process and the right to a fair trial","text":"Please provide updated information on the total number of lawyers disbarred since\nMay 2020 and the grounds for their disbarment.","annex":2},{"id":"a-hrc-52-68-p0027-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"27","seq":101,"section":"E. Citizenship","text":"Please provide details on the total number of cases of revocation of citizenship by the\nBelarus authorities, if any, including on the grounds for revoking citizenship since May 2020.","annex":2},{"id":"a-hrc-52-68-p0028-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"28","seq":102,"section":"F. Implementation of previous recommendations","text":"Please outline any steps taken to implement recommendations contained in the last\ntwo OHCHR reports on Belarus (A/HRC/49/71 and A/HRC/46/4).","annex":2},{"id":"a-hrc-52-68-p0029-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"29","seq":103,"section":"G. Access","text":"Please reply to the High Commissioner’s Note Verbale dated 23 August 2022\nrequesting access to Belarus and grant such access.","annex":2},{"id":"a-hrc-52-68-p0030-a2","rec_id":"recQ5W70vZA26WyLA","symbol":"A/HRC/52/68","n":"30","seq":104,"section":"G. Access","text":"The Office of the United Nations High Commissioner for Human Rights avails itself\nof the opportunity to renew to the Permanent Mission of the Republic of Belarus to the United\nNations Office and other international organizations in Geneva the assurances of its highest\nconsideration.","annex":2},{"id":"a-hrc-55-61-u0000","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":null,"seq":0,"section":null,"text":"United Nations                                                                                    A/HRC/55/61\nGeneral Assembly                                                           Distr.: General\n25 March 2024","unnumbered":true},{"id":"a-hrc-55-61-u0001","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":null,"seq":1,"section":null,"text":"Human Rights Council\nFifty-fifth session\n26 February–5 April 2024\nAgenda items 2 and 4\nAnnual report of the United Nations High Commissioner\nfor Human Rights and reports of the Office of the\nHigh Commissioner and the Secretary-General\nHuman rights situations that require the Council’s attention","unnumbered":true},{"id":"a-hrc-55-61-u0002","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":null,"seq":2,"section":null,"text":"Summary\nThe present report, submitted pursuant to Human Rights Council resolution 52/29,\npresents an examination of the human rights situation in Belarus since May 2020. The report\naddresses alleged human rights violations about which the Office of the United Nations High\nCommissioner for Human Rights has collected, consolidated, preserved and analysed\ninformation and evidence, makes conclusions under the applicable international legal\nframework and offers recommendations to the Government and the international community.","unnumbered":true},{"id":"a-hrc-55-61-u0003","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":null,"seq":3,"section":null,"text":"* The present report was submitted to the conference services for processing after the deadline so as to\ninclude the most recent information.\n** The annexes to the present report are circulated as received, in the language of submission only.","unnumbered":true},{"id":"a-hrc-55-61-p0001","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"1","seq":4,"section":"I. Introduction","text":"The present report is submitted pursuant to Human Rights Council resolution 52/29,\nin which the Council extended, for a period of one year, the mandate of the United Nations\nHigh Commissioner for Human Rights to monitor and report on the situation of human rights\nin Belarus and to examine all alleged human rights violations committed in the country in the\naftermath of the 2020 presidential elections and requested the High Commissioner to present\na comprehensive report to the Council at its fifty-fifth session."},{"id":"a-hrc-55-61-p0002","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"2","seq":5,"section":"I. Introduction","text":"The Office of United Nations High Commissioner for Human Rights (OHCHR)\nimplemented the mandate, with advice from three experts appointed by the High\nCommissioner: Karinna Moskalenko (Russian Federation), Susan Bazilli (Canada) and\nMonika Płatek (Poland). OHCHR renews its appreciation to the experts, Member States, the\nSpecial Rapporteur on the situation of human rights in Belarus, the Organization for Security\nand Cooperation in Europe (OSCE) and civil society organizations for the material shared\nwith and support provided in the discharge of this mandate. OHCHR also extends its\nappreciation to the victims, survivors and witnesses who shared their experiences and other\nrelevant information."},{"id":"a-hrc-55-61-p0003","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"3","seq":6,"section":"I. Introduction","text":"In its resolution 52/29, the Human Rights Council again urged the Belarusian\nauthorities to cooperate with OHCHR in executing its mandate, in particular by granting\nunhindered access to the country. OHCHR regrets that the Belarusian Government has not\nresponded to two notes verbales, dated 22 June and 1 November 2023, seeking access to the\ncountry and enclosing a list of issues. 1"},{"id":"a-hrc-55-61-p0004","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"4","seq":7,"section":"I. Introduction","text":"The report, which covers the period from 1 May 2020 to 31 December 2023, focuses\non developments in 2023 and supplements the previous findings of OHCHR on violations\nthat occurred between 1 May 2020 and 31 December 2022 as set out in previous reports. 2"},{"id":"a-hrc-55-61-p0005","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"5","seq":8,"section":"II. Methodology and standard of proof","text":"The present report is based on the totality of information and evidence collected by\nOHCHR since the mandate was provided for in Human Rights Council resolution 46/20. A\ntotal of 657 first-hand interviews (390 with males (3 boys), 264 with females (1 girl) and\n3 with non-binary individuals) were conducted, in accordance with OHCHR methodology,\nwith victims and witnesses, non-governmental organizations, journalists, lawyers and\nmedical personnel. Of that number, 305 interviews (166 with males (1 boy), 136 with females\n(1 girl) and 3 with non-binary individuals) were conducted since the last report.3 Findings\narising from first-hand interviews are supported by more than 5,400 items of information and\nevidence, of which over 2,000 were collected in 2023, as well as 229 written submissions\nfrom victims, witnesses and non-governmental organizations, of which 43 were received in\n2023.4 OHCHR reports are based on verified information collected from sources that are\nassessed as credible and reliable, according to OHCHR methodology. Information is included\nwhere the “reasonable grounds to believe” standard of proof has been met."},{"id":"a-hrc-55-61-p0006","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"6","seq":9,"section":"A. Freedom of expression, association and peaceful assembly","text":"The cumulative effect of violations of freedom of expression, association and\nassembly in Belarus since 1 May 2020 has been the closure of independent civic space, which\nhas effectively deprived the population of its ability to exercise those rights. No opposition\nparty was able to re-register for the February 2024 parliamentary election and over\n1,500 non-governmental organizations, all independent trade unions and hundreds of media\noutlets have been closed. Courts, government ministries and security agencies have acted in\nconcert in implementing the above restrictions."},{"id":"a-hrc-55-61-p0007","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"7","seq":10,"section":"A. Freedom of expression, association and peaceful assembly","text":"In 2023, the Law on Political Parties was amended, requiring all existing political\nparties to meet stringent criteria for re-registration within three months or to be dissolved by\nthe Supreme Court.5 Many parties found the requirements impossible to meet, owing, inter\nalia, to the possible risk that their members would be named as members of groups that\noppose the Government, exposing them to the danger of arbitrary arrest. The process resulted\nin the dissolution of all opposition parties. Out of 15 parties, only 4, aligned with the\nGovernment, were registered as eligible to participate in the February 2024 parliamentary\nelection.6 In November 2023 the President of Belarus stated: “we cleansed the playing field\nof decorative associations and of those whose efforts are aimed at undermining the\nfoundations of the constitutional system of our country”.7"},{"id":"a-hrc-55-61-p0008","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"8","seq":11,"section":"A. Freedom of expression, association and peaceful assembly","text":"Amendments to the Law on Public Associations, adopted on 14 February 2023, added\n“inconsistency of activities of public association with the main directions of domestic and\nforeign policy and the concept of national security” as new grounds for the dissolution of a\npublic association.8 Further, the systematic efforts to close civil society organizations, which\nbegan in 2021, continued, 9 impacting cultural and humanitarian organizations. As at\n31 December 2023, at least 960 civil society organizations had been dissolved and 550 more\nhad been forced to close for fear of persecution, reprisals, intimidation or violence. 10 All\nindependent trade unions had previously been dissolved, most in 2021 and 2022.11"},{"id":"a-hrc-55-61-p0009","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"9","seq":12,"section":"A. Freedom of expression, association and peaceful assembly","text":"In 2023, at least 20 prominent human rights defenders and trade unionists were\nsentenced to prison terms ranging from 5 to almost 15 years and received high fines. Included\nin those convictions, in February and March 2023, were staff and volunteers of the Viasna\nHuman Rights Centre, including Marfa Rabkova, Andrei Chapiuk, Ales Bialiatski, Valiantsin\nStefanovich and Dzmitry Salauyou (in absentia). In June, Nasta Loika of Human Constanta\nwas sentenced; in court she stated that she had been subjected to ill-treatment and torture.12\nAlso in June, the acting chairperson of Belarusian Radio and Electronic Workers’ Union,\nVasil Berasnieu, was convicted and sent to prison. Some of the above individuals were\nsubsequently added to the Government’s list of “terrorist organizations” or “terrorist\nformations”.13"},{"id":"a-hrc-55-61-p0010","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"10","seq":13,"section":"A. Freedom of expression, association and peaceful assembly","text":"Repression of free media continued, with at least 34 raids by Belarusian security\nforces at the editorial offices and private homes of journalists and 46 arrests and 16 verdicts\nagainst journalists and media workers in 2023. As at 31 December 2023, 23 male and nine\nfemale journalists had been arbitrarily detained. 14 OHCHR also confirmed the unlawful\nclosure15 of the independent news and media website “Tut.By” and other regional media in\nMinsk, Brest and Gomel."},{"id":"a-hrc-55-61-p0011","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"11","seq":14,"section":"A. Freedom of expression, association and peaceful assembly","text":"In 2023, OHCHR observed an intensified use of broad counter-terrorism and\ncounter-extremism legislation to restrict civic space,16 with laws adopted or amended since\n2021 increasingly being used in a systematic manner to oppress and punish real or perceived\nopponents. Under such legislation, Belarus law enforcement and judicial authorities across\nthe country arbitrarily arrested and detained, prosecuted and punished thousands of\nBelarusians in the course of 2023 for having exercised their human rights or freedoms, in\nmany cases for acts that were not crimes at the time of their commission."},{"id":"a-hrc-55-61-p0012","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"12","seq":15,"section":"A. Freedom of expression, association and peaceful assembly","text":"As at 31 December 2023, the Belarusian Government had designated 167 entities as\n“extremist formations” and two as “extremist organizations”, including 21 media agencies,\nthe Belarusian Association of Journalists and the Viasna Human Rights Centre. Cooperation\nwith those entities entails risk of criminal prosecution on charges of facilitating extremist\nactivities.17 OHCHR also found there was intensification of punitive measures for donations\nmade to extremist entities, in some cases even prior to the designation of the organization or\nentity as extremist, entailing criminal liability on charges of financing of extremism. 18"},{"id":"a-hrc-55-61-p0013","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"13","seq":16,"section":"A. Freedom of expression, association and peaceful assembly","text":"As at 31 December 2023, there were 4,584 entries on the Government’s list of list of\n“terrorist organizations” or “terrorist formations”. 19 During the reporting period, at least\n16,000 criminal cases related to extremism have been registered. The number of\nadministrative charges for the dissemination of extremist materials 20 increased dramatically\nthroughout 2023 (see sect. B below). In many cases, charges were presented for alleged\ndissemination, which took place prior to the designation of the material as extremist."},{"id":"a-hrc-55-61-p0014","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"14","seq":17,"section":"A. Freedom of expression, association and peaceful assembly","text":"Persons convicted on criminal charges for acts deemed as extremist face inclusion on\nthe above-mentioned list of “terrorist organizations” or “terrorist formations”,21 which has\nseveral negative consequences, including: banning from certain professions; having their\nfinancial transactions monitored; difficulties in accessing services; and heightened risk of\ndiscrimination and harassment, such as dismissal from work or from university (see sect. G\nbelow). As at 31 December 2023, the rapidly expanding list contained 3,654 names\n(2,862 men and 792 women). OHCHR previously found that the use of counter-terrorism and\ncounter-terrorism legislation in Belarus is overly broad and is used to suppress dissenting\nvoices and to curtail access to information."},{"id":"a-hrc-55-61-p0015","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"15","seq":18,"section":"B. Arbitrary arrest and detention and the right to a fair trial","text":"According to the cumulative findings of OHCHR since 2020, tens of thousands of\nBelarusians, including hundreds of children, have been arbitrarily arrested and detained on\npolitical grounds. Of the 657 individuals interviewed since the beginning of the examination,\n540 had been arrested and detained in an arbitrary manner. Those arrests and detentions\noccurred as a result of individuals exercising their rights to freedom of expression, association\nand peaceful assembly, without being granted their right to a fair trial or adherence to\ndetention safeguards. While those violations were at their peak in 2020–2021, they continued\nthroughout 2022–2023 in a systematic and widespread manner, affecting thousands of\nBelarusians. 22 In 2023, against a backdrop of severe repression of civic space, no\ndemonstrations took place, although thousands continued to be arbitrarily arrested and\ndetained for having exercised their freedom of expression and or assembly as far back as\n2020.23 At 31 December 2023, at least 1,477 persons (1,308 men, 168 women, one boy) 24\nremained in detention, either facing or serving sentences for criminal or administrative\ncharges that OHCHR has determined to be politically motivated. 25"},{"id":"a-hrc-55-61-p0016","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"16","seq":19,"section":"B. Arbitrary arrest and detention and the right to a fair trial","text":"Security forces used facial recognition software, social media and Internet monitoring,\nand hacking and coerced searches of mobile devices to identify persons who were\nsubsequently arrested from homes, workplaces and streets across Belarus. 26 Most arrests in\n2022–2023 were carried out by large teams of police officers (mostly from the Main\nDirectorate for Combating Organized Crime and Corruption of the Ministry of Internal\nAffairs of Belarus, also known as the Committee of State Security). Most of those arrested\ndescribed being arrested without a warrant or without an opportunity to read what was\npresented to them. Almost all were subjected to threats and intimidation, many to\nunnecessary or/and disproportionate force, sometimes in the presence of their children (see\nsect. H below), to compel them to hand over and unlock mobile phones and other electronic\ndevices. OHCHR documented 198 arrests and house searches in 2022, with an additional 59\nin 2023 in Minsk and in all six regions of Belarus where security forces, in particular from\nCommittee of State Security, arrived in excessive numbers, using unnecessary and\ndisproportionate force towards men, women and non-binary individuals who did not pose\nany threat or resist arrest. Security forces subjected them to beatings, including with batons,\nbats or household objects, in some cases using stun guns, applying kicks, painful restraints,\nthreats, insults and intimidation, including several instances where people were held at\ngunpoint. While women were also subjected to physical violence, psychological violence\ntowards them was particularly intense. LGBTQ persons or those perceived as such owing to\ntheir general appearance were treated in a particularly violent and humiliating manner."},{"id":"a-hrc-55-61-p0017","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"17","seq":20,"section":"B. Arbitrary arrest and detention and the right to a fair trial","text":"Since 2020 and continuing through 2023, security forces have used unnecessary and\ndisproportionate force across Belarus. This pattern, which has been perpetrated with\nimpunity, with the approval and encouragement of the highest authorities, 27 has resulted in\ndozens of serious injuries, including cases of the arbitrary deprivation of life, which\nauthorities in Belarus have failed to investigate or provide redress for."},{"id":"a-hrc-55-61-p0018","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"18","seq":21,"section":"B. Arbitrary arrest and detention and the right to a fair trial","text":"Illegal searches of private property and of electronic communications 28 were carried\nout to locate photos or videos of individuals who had taken part in protests in 2020, had\nsubscriptions to “extremist” or “anti-government” social media or possessed items or insignia\nconsidered to symbolize the opposition, even simply red and white clothing. In several cases\nsecurity officers took out subscriptions to prohibited social media channels in the name of\ntheir victims after gaining control of their electronic devices. In some cases, money or\nbelongings were confiscated without documentation. Most of the people arrested in 2023\nwere initially charged under article 19.11 of the Code of Administrative Offences for the\ndissemination of extremist materials (with over 2,800 cases registered in 2023), sometimes\non unfounded charges under article 24.3 on disobeying orders of public officials or under\narticle 19.1 on petty hooliganism.29"},{"id":"a-hrc-55-61-p0019","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"19","seq":22,"section":"B. Arbitrary arrest and detention and the right to a fair trial","text":"Sentences for administrative offences increased from an average of 8 to 10 days in\n2020 to 13 to15 days in 2022–2023. In numerous cases, an initial order of administrative\ndetention for 15 days was renewed, sometimes repeatedly, on evidence that victims stated\nwas fabricated or on the basis of the evidence re-used multiple times until criminal charges\nwere filed. Most criminal charges were filed for breach of article 342 of the Criminal Code\non the “organization and preparation of actions that grossly violate public order, or active\nparticipation in them”, for which at least 862 verdicts were issued in 2023. 30 In 2023,\nOHCHR observed an increasing use of criminal charges for acts that were previously subject\nto administrative charges, allowing for prolonged periods of pretrial detention. OHCHR also\nobserved an increased use of charges of “extremism” and “terrorism” related offences,\ncarrying harsher sentences (see also sect. A above).31 Since 2020, there has been a significant\nincrease in the use of article 411 of the Criminal Code on “malicious disobedience to the\nrequirements of the administration of a correctional institution” in order to extend, sometimes\nrepeatedly and without a fair trial, the detention of persons already serving sentences for other\nconvictions.32"},{"id":"a-hrc-55-61-p0020","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"20","seq":23,"section":"B. Arbitrary arrest and detention and the right to a fair trial","text":"Systematic violations of the rights to due process and a fair trial in both administrative\nand criminal cases continued, following previously established patterns.33 Since 1 May 2020,\nover 5,500 individuals, including at least 55 children, have been criminally convicted on\ncharges assessed by OHCHR to be politically motivated in trials that lacked fairness. All\ninterviewees who had been subject to arrest and/or detention in 2022 and 2023 raised\nconcerns about due process and fair trial rights. According to victims and lawyers\ninterviewed, documentation provided and analysis by civil society organizations,34 sentences\nappeared predetermined, increasingly arbitrary and harsh. Virtually all sentences were upheld\non appeal. This situation, coupled with institutionalized impunity (see sect. V below), points\nto non-existence of domestic remedies to challenge arbitrary detention and all subsequent\nviolations against persons deprived of their liberty. A particularly alarming recent\ndevelopment was the total denial of access of lawyers to several high-profile political\ndetainees serving sentences (see sect. F below)."},{"id":"a-hrc-55-61-p0021","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"21","seq":24,"section":"B. Arbitrary arrest and detention and the right to a fair trial","text":"The number of licenced lawyers dropped from 2,200 in the beginning of 2020 to 1,603\nas at 31 December 2023.35 Belarus authorities disbarred at least 131 lawyers (78 men and\n53 women) between September 2020 and December 2023.36 Others no longer practiced or\nleft the country out of fear for their safety. The pressure on lawyers who are defending people\nwith politically motivated charges further intensified in 2022–2023: in addition to disbarment\nand arrests, OHCHR documented cases of administrative detention of up to 30 days,\nincluding torture and ill-treatment of lawyers by Committee of State Security and criminal\ncharges. As at 31 December 2023, eight men and two women lawyers had been subjected to\ncriminal prosecution and four men and two women lawyers were being held in detention.37"},{"id":"a-hrc-55-61-p0022","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"22","seq":25,"section":"C. Torture and other cruel, inhuman or degrading treatment or","text":"Since 2020, thousands of Belarusians, including dozens of children, have been\nsubjected to systematic and discriminatory practices amounting to cruel, inhuman or\ndegrading treatment or punishment in detention facilities across Belarus. Belarusian\nauthorities are responsible for four deaths in custody that they have failed to prevent and\ninvestigate. OHCHR has also found that conditions in temporary detention facilities for those\ndetained on politically motivated charges may amount to cruel, inhuman or degrading\ntreatment, and in some cases torture.38"},{"id":"a-hrc-55-61-p0023","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"23","seq":26,"section":"C. Torture and other cruel, inhuman or degrading treatment or","text":"Out of all the 657 individuals interviewed by OHCHR since 2020, 29 per cent alleged\nthat they had been tortured and 61 per cent alleged ill-treatment. Building on previous\nreporting, in 2023, OHCHR gathered and consolidated further evidence of torture by\nBelarusian police in August, September and October 2020, with fully verified cases in Minsk,\nGomel, Slutsk, Mozyr and Pinsk. Some victims sustained long-lasting and even life-changing\ninjuries, as verified by the OHCHR forensic assessment. Injuries included aneurysms,\nhearing loss, movement limitations in shoulder, hip and knee joints, bone fractures in arms,\nlegs, nose and spine and damage to the nerves. Many victims were diagnosed with severely\ndebilitating health effects, including high blood pressure, chronic renal diseases, depression,\npost-traumatic stress disorder, panic attacks and sleeping difficulties. Most victims were men,\nincluding one person with disabilities."},{"id":"a-hrc-55-61-p0024","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"24","seq":27,"section":"C. Torture and other cruel, inhuman or degrading treatment or","text":"OHCHR found that those arrested faced intense pressure and violence, in many cases\namounting to torture, during their initial interrogation and search for evidence in 38 cases in\n2022 and 9 cases in 202339. Violence took place after arrests in police vehicles or/and during\ninterrogations at the offices of the Committee of State Security in Minsk and police stations\nin all six regions of Belarus. To extract confessions, obtain information, punish, intimidate,\nhumiliate or coerce victims, officers used physical violence, including beatings with metal\nrods, wooden bats or batons, kicking and beating on different parts of the body, causing\nsevere physical pain. In several cases, detainees were forced into excruciating stress positions\nfor prolonged periods and in at least two cases officers of the Committee of State Security\nnearly suffocated detainees by applying masks or bags to their faces. Physical violence to\nvictims was accompanied by threats, coercion and intimidation, including threats of death,\ngender-based violence, including sexual violence, harm to family members or/and removal\nof children. Interrogations, which lasted for hours, were carried out without a lawyer. Most\nallegations of torture documented by OHCHR took place in the central office of the\nCommittee of State Security in Minsk, in several cases in the presence of, and in some cases\nwith the active participation of, the most senior officers of the Committee’s Department 3 for\ncountering extremism.40"},{"id":"a-hrc-55-61-p0025","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"25","seq":28,"section":"C. Torture and other cruel, inhuman or degrading treatment or","text":"OHCHR documented 17 cases where officers of the Committee of State Security used\nstun guns to inflict pain during initial arrest or interrogation. Forensic assessment by OHCHR\nconfirmed their repeated use on several parts of the bodies of victims, in some cases\namounting to sexual violence, corroborating accounts of victims of the use of stun guns in\nsituations and in a manner where their use was not necessary to avoid flight, protect personal\nsafety or maintain security, but rather for punishment or coercion."},{"id":"a-hrc-55-61-p0026","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"26","seq":29,"section":"D. Sexual and gender-based violence","text":"Based on cumulative evidence collected since 2021, OHCHR has reasonable grounds\nto believe that Belarusian security forces committed rape and other forms of sexual and\ngender-based violence, including sexualized torture and forced nudity, on men, boys, women\nand non-binary individuals in police vehicles, police stations and detention facilities between\n1 May 2020 and 31 December 2023.41 Over 32 per cent of all 657 interviewees reported that\nthey had been victims of gender-based violence, including sexual violence. The most\ncommon forms of sexual and gender-based violence were unnecessary strip and cavity\nsearches in the context of arrest, interrogation or detention and rape threats, which were\nwidespread and made by persons representing the authorities."},{"id":"a-hrc-55-61-p0027","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"27","seq":30,"section":"D. Sexual and gender-based violence","text":"Police, Committee of State Security and prison officers in Brest, Gomel, Grodno,\nMinsk (city and region) and Mogilev regions used rape threats, often accompanied by\nphysical violence, to degrade, intimidate, coerce or exert control. Threats contained brutal,\nexplicit and aggressive language, often with homophobic elements. Officers openly made\nthreats, showing confidence in their impunity for such acts. Men were threatened with being\nraped with a baton, being sent to prison cells where they could be raped by other detainees\nor having their spouses or daughters subjected to sexual violence. Women were threatened\nwith gang rape. Threats and insults against LGBTQ persons underscored hatred based on\nsexual orientation or gender identity against persons perceived not to conform with so-called\ntraditional values. OHCHR also documented cases of the forced outing of LGBTQ persons\nor those misidentified as LGBTQ detained on politically motivated grounds by Belarusian\nsecurity forces, “repentance” videos, recorded under duress and published online or on\ntelevision, and smear posters disseminated in victims’ neighbourhoods."},{"id":"a-hrc-55-61-p0028","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"28","seq":31,"section":"D. Sexual and gender-based violence","text":"OHCHR documented 121 incidents of unnecessary and degrading strip and cavity\nsearches in detention facilities.42 They were performed by one or more individuals whose\npositions the detainees did not know, sometimes by individuals of the opposite gender and\noftentimes in locations lacking privacy. Some detainees reported being held down for\nsearches and others reported being afraid owing to the aggressive behaviour and language\nused by those conducting interviews. Detainees, including men, boys and women, as well as\nmenstruating women, were asked to squat repeatedly while naked and some were subjected\nto several hours of forced nudity.43 Many searches were not carried out for security purposes,\nbut rather to intimidate and humiliate, which could amount to ill-treatment or torture.44"},{"id":"a-hrc-55-61-p0029","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"29","seq":32,"section":"D. Sexual and gender-based violence","text":"In what may amount to ill-treatment or in some cases torture, OHCHR found that\nwomen held on politically motivated charges lacked access to health care specific to their\nneeds or had it actively denied.45 For example, a woman arbitrarily detained in Minsk Prison\n(known as SIZO No. 1) was denied obstetric care despite repeated requests and visible signs\nof her advanced pregnancy. Committee of State Security interrogators referred to her\npregnancy, threatened her with death and sent her to an isolation cell without ventilation. The\nvictim reported that she fainted and was administered medication before being returned to\nthe same cell. That same night, six months pregnant and without any medical care, she gave\nbirth to a stillborn boy in her cell. She was denied any official acknowledgement of the\npregnancy or stillbirth and threatened with punishment if she did not stay silent."},{"id":"a-hrc-55-61-p0030","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"30","seq":33,"section":"E. Discriminatory, degrading and punitive conditions and treatment in","text":"OHCHR consolidated further evidence of discriminatory and punitive treatment and\nconditions of those held on politically motivated charges in temporary detention facilities\nthroughout Belarus in 2023.46 Unlike other detainees, those detained on politically motivated\ncharges were held in severely overcrowded and badly ventilated cells, inadequately heated\nand unhygienic, without mattresses, bedding, basic hygienic items or warm clothes, including\nrestrictions or total denial of access to bathing facilities, time outside, correspondence or\npackages. Small punishment cells (“kartser”), intended for one person, were used to hold\n10 to 15 detainees. Detainees were systematically deprived of sleep by uninterrupted artificial\nlightning and were repeatedly forced to stay wake at night, subjected to frequent transfers\nbetween cells and denied needed medical assistance. Conditions were the same for men and\nwomen who were held in the same facilities but in separate cells. OHCHR also found that\nthose detained on politically motivated charges were systematically deprived of basic\nhygienic items, including menstruation pads, humiliated when asking for them and often\ndenied access to those items in packages sent to them. Such conditions and practices may\namount to cruel, inhuman or degrading treatment or punishment or, in some cases, to\ntorture. 47 OHCHR has established that the conditions and practices of detention were in\naccordance with instructions given to the guards and directors of temporary detention\nfacilities; several victims from different facilities consistently reported of being specifically\ntold by the guards that the conditions under which they were being held were to be imposed\non those referred to as “political detainees” or “terrorists”."},{"id":"a-hrc-55-61-p0031","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"31","seq":34,"section":"E. Discriminatory, degrading and punitive conditions and treatment in","text":"OHCHR found that detainees held on politically motivated charges were\nsystematically included on a registry of those prone to extremism and that their clothes and\ncells were marked with yellow tags. This registration and marking determined their treatment\nand conditions in the penal colonies and during transfers, which appeared both discriminatory\nand punitive.48 In contrast to other detainees, those on the registry were handcuffed during\nall transfers, checked more frequently, always had to stand in the first row for inspections,\nhad to sleep on upper bunk beds, had their movements inside the colony and their\ncommunication and visitation rights restricted and were not eligible for parole."},{"id":"a-hrc-55-61-p0032","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"32","seq":35,"section":"E. Discriminatory, degrading and punitive conditions and treatment in","text":"In addition, OHCHR found that detainees held on politically motivated grounds were\nsubjected to what appeared to be a system of arbitrary and disproportionate punishment.49\nDetainees released from penal colonies across Belarus consistently told of having been put\nunder strict observation upon arrival, being quickly found to be in breach of prison rules and\npunished on any pretext, such as an unbuttoned button or a sticker affixed on the bedside\ntable by the guard. This was followed by repeated offences and their subsequent designation\nas persistent offenders, triggering negative consequences for prisoners, including potentially\nbeing charged and further imprisoned for malicious disobedience. 50 The punishments for\nthose offences appeared disproportionate and sometimes baseless. The conditions in\npunishment cells (known as “SHIZO”), where detainees were held for periods totalling up to\n30 days in complete isolation, with family members unaware of their condition and\nwhereabouts, may amount to torture. The cells were so cold that detainees were unable to\nsleep and had to exercise to keep warm. Detainees were not allowed any personal items or\nactivity, nor were they allowed to sleep during the day. Further, sentencing was often\nprolonged, sometimes repeatedly, on the expected end date of prison sentences."},{"id":"a-hrc-55-61-p0033","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"33","seq":36,"section":"E. Discriminatory, degrading and punitive conditions and treatment in","text":"OHCHR found that prisoners held on politically motivated charges in penal colonies\nacross Belarus were subjected to compulsory and exploitative labour in unsafe working\nconditions. Some interviewees reported accidents, injuries and negative health effects due to\nlack of training, work clothing or protective equipment. Compensation for the workweek of\nfive or six days was usually a few roubles or nothing at all.51"},{"id":"a-hrc-55-61-p0034","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"34","seq":37,"section":"F. Enforced disappearance","text":"Between August 2020 and March 2023, OHCHR documented 27 cases 52 in which\nmen and women in Brest, Minsk and Vitebsk were brought to police stations and held\nbetween 1 and 14 days without a lawyer, with their families denied information on their\nwhereabouts. Those cases may have amounted to enforced disappearance. Most of the\npersons arrested were ill-treated."},{"id":"a-hrc-55-61-p0035","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"35","seq":38,"section":"F. Enforced disappearance","text":"OHCHR verified as accurate numerous public reports53 that, as at 31 December 2023,\nseveral high-profile members of the opposition in prison, including Viktar Babaryka, Maria\nKalesnikava, Ihar Losik, Mikalai Statkevich, Siarhei Tsikhanouski and Maxim Znak, were\nheld incommunicado for prolonged periods, extending up to 11 months. Family members and\nlawyers have been denied the possibility to meet them or to obtain any information on their\nwhereabouts and condition. The above cases may amount to enforced disappearance.54 Some\ndetainees were only heard of when they were brought to a hospital for emergency treatment,\ntriggering serious concerns for their physical and mental integrity and for their lives. After\nhospital visits, detainees were sent back to isolation. The intense psychological suffering of\nfamily members caused by this seemingly intentional punitive treatment of their loved ones,\nwithout being able to ascertain whether they remained alive, may amount to torture. 55\nFurthermore, following the arrest in March 2023 of six lawyers representing those prisoners\nand the subsequent disbarment of at least three of them, fear of harassment, disbarment and\ncriminal prosecution has made it impossible for the detainees to engage new lawyers."},{"id":"a-hrc-55-61-p0036","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"36","seq":39,"section":"G. Unlawful deaths","text":"Since 2020, OHCHR previously documented five deaths that allegedly resulted from\nunnecessary or disproportionate force used during the protests in 2020 or from a failure to\nprotect life in detention.56 OHCHR collected further testimonies, information and evidence\nrelating to three deaths allegedly resulting from unnecessary or disproportionate use of force\nduring the protests in 2020 or in custody. OHCHR has reasonable grounds to believe that one\ndeath (Nikita Kryvtsov) was not due to suicide, as alleged by Belarusian authorities, and two\nother deaths (blogger Nikolai Klimovich and artist Ales Pushkin) resulted from medical\nnegligence in detention. OHCHR found reasonable grounds to believe that the three deaths\nmay amount to a violation of the right to life. While investigations were purportedly carried\nout, they were not conducted in accordance with international standards according to\ninformation available to OHCHR. 57 International human rights law sets out the obligation of\nStates to investigate potentially unlawful deprivations of life and, where appropriate, to\nprosecute the perpetrators. 58 OHCHR continues to investigate 16 other cases of possible\nunlawful deaths in custody or resulting from the unnecessary or disproportionate use of force\nby Belarusian security forces."},{"id":"a-hrc-55-61-p0037","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"37","seq":40,"section":"H. Rights of the child","text":"OHCHR previously reported that, between 9 and 14 August 2020, 700 children were\narbitrarily arrested.59 An OHCHR investigation found that additional widespread arbitrary\narrests of hundreds of children were carried out throughout Belarus in 2020–2021, in the\ncontext of election-related protests. Aged between 11 and 17, 85 per cent of those arrested\nwere boys. While most were arrested only briefly, over 100 were transferred to detention\nfacilities and over 50 were criminally charged. Three related arrests of children were carried\nout in 2023. As at 31 December 2023, 10 persons (all male), who were under age 18 at the\ntime of their arrest, remained in detention on politically motivated charges. The arrests and\nprosecutions also violated the rights of the children to freedom of expression, association and\npeaceful assembly."},{"id":"a-hrc-55-61-p0038","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"38","seq":41,"section":"H. Rights of the child","text":"As at 31 December 2023, 50 boys and 5 girls had been sentenced in criminal cases on\npolitically motivated charges. Further, OHCHR found that many children were deprived of\nprotections afforded under international law: children below the age of criminal\nresponsibility were criminally charged; some children were interrogated without a lawyer or\nparent present; there were no juvenile courts; and in several cases alternatives to pretrial\ndetention and imprisonment were not considered. Fearing a long prison sentence, Dmitry\nStakhovsky, who had been arrested in November 2020, then aged 17, committed suicide in\nMay 2021. Instead of protecting the particularly vulnerable boy (an orphan), authorities\npressured him to self-incriminate and charged him for the organization of mass riots. Belarus\nauthorities failed to conduct an effective investigation into his death. Furthermore, as at\n31 December 2023, the Government had placed at least 48 persons (43 male, 5 female), who\nwere under age 18 at the time of the offence with which they were charged, on its list of\n“terrorist organizations” or “terrorist formations”, with severe negative impact on their rights."},{"id":"a-hrc-55-61-p0039","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"39","seq":42,"section":"H. Rights of the child","text":"In August and September 2020, children protesting or near protest sites were subjected\nto unnecessary or disproportionate force during arrests and to ill-treatment or possibly torture\nin detention. In cases verified by OHCHR, children were beaten, including with batons,\nthrown, kicked and had their arms twisted by the police in Minsk and in the Brest, Gomel\nand Minsk regions. Children’s hospital records show head injuries and brain concussions,\nfractures of facial and back bones, bruises and hematoma all over the body, a gunshot wound\nand an open shrapnel fracture. Five boys were subjected to sexual violence. Once held at\npolice stations or pretrial facilities, children were held kneeling or standing against the wall\nfor prolonged periods, beaten, kicked, threatened and intimidated, deprived of sleep and held\ntogether with adults in the same inhumane conditions.60"},{"id":"a-hrc-55-61-p0040","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"40","seq":43,"section":"H. Rights of the child","text":"OHCHR verified 11 cases where children were among those ill-treated in 2022–2023,\nincluding during house searches. Their reported ill-treatment included being forced to record\nself-incriminating videos without the presence of a lawyer or parent, repeated strip-searches\nand humiliating comments. In 16 cases across Belarus, boys and girls witnessed heavily\narmed security forces subjecting their parents to violence and threats 61 , including being\nroughly handcuffed, held at gunpoint, beaten, kicked and threatened with the removal of their\nchildren. In 11 of those cases, security forces threatened and insulted the children and held\nthem inside their homes, sometimes at gunpoint. In 32 accounts by children and professionals\nworking with them, the profound psychological trauma and negative physical impact\ntriggered by those events has been recorded."},{"id":"a-hrc-55-61-p0041","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"41","seq":44,"section":"H. Rights of the child","text":"The widespread arbitrary arrest and detention of parents on political grounds violates\nthe right to family life and the best interest of the child.62 In numerous cases, authorities failed\nto consider child-care responsibilities as a mitigating circumstance when deciding to deprive\nindividuals of their liberty. In 14 cases, parents were led away without being allowed to\nexplain their situation to their children or were taken while their children were at school. In\n10 cases, children were left without care or taken to orphanages; in other cases, parents were\nforced under duress to transfer the custody of their children to relatives or friends. Authorities\nused the so-called “socially dangerous situations” procedure63 to remove children from their\nparents in ways that seemed more focused on pressuring and punishing parents than\nsafeguarding the best interests of the child. OHCHR previously found that child removal\nthreats were a significant factor driving Belarusians into exile. 64"},{"id":"a-hrc-55-61-p0042","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"42","seq":45,"section":"I. Right to work and education","text":"OHCHR found systematic and widespread violations of the right to work and the right\nto education of thousands real or perceived opponents. Starting in 2020, discriminatory\ndismissals and expulsions were carried out in violation of the prohibition of discrimination\nin access to work and education65 and in what appears to be arbitrary and disproportionate\npunishment. Those violations, which continued until the end of the reporting period, forced\nmany Belarusians to exile and, in some cases, were used in reprisal against family members\nof primary victims. Further, they were aggravated by the obliteration of the independent\nlabour rights movement.66"},{"id":"a-hrc-55-61-p0043","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"43","seq":46,"section":"I. Right to work and education","text":"Dozens of interviewees confirmed the publicly reported67 patterns of violations of the\nright to work and education. OHCHR found widespread dismissals from work and expulsions\nfrom universities after detention under administrative or criminal charges on politically\nmotivated grounds. The Labour Code and, from January 2022 onwards, the Education Code\ninclude absences from work or classes for serving an administrative penalty as grounds for\ndismissal.68 Some interviewees were pressured to resign or were not rehired. Many reported\nhaving been told that they were dismissed following instructions owing to their “disloyalty\nto the State” and named the Committee of State Security as the entity behind such\ninstructions."},{"id":"a-hrc-55-61-p0044","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"44","seq":47,"section":"I. Right to work and education","text":"OHCHR found that expulsions, dismissals, pressure to resign and non-extension of\ncontracts also targeted those who, without being detained, had participated in protests, been\nactive in the student movement, displayed protest symbols or subscribed to social media\nchannels determined as extremist. Most interviewees reported an inability to find new work\nfollowing dismissals. Many referred to a blacklist used by both public and private sector\nemployers to run background checks on prospective employees and to instructions given to\nState-owned and private companies by public institutions in this regard. At universities,\nrepression had intensified. 69 According to interviewees, universities actively discouraged\nparticipation in protests or expressions of anti-Government views. Students were threatened\nwith negative consequences, including expulsion, which, for State-funded students, also\nentails an obligation to reimburse education costs 70 and, for young men, conscription for\nmilitary service.71"},{"id":"a-hrc-55-61-p0045","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"45","seq":48,"section":"I. Right to work and education","text":"As of 2021, additional positions of “deputy director for security issues” were created\nin State-owned companies and public institutions, including universities and medical\ninstitutions, to conduct background checks on employees and ensure “ideological\nalignment”. Furthermore, anyone on the Government’s list of “terrorist organizations” or\n“terrorist formations” (see sect. A above) is banned from engaging in educational and\npublishing activities and from holding public office. The Law on Licencing, adopted in\n64 A/HRC/52/68 and A/HRC/52/68/Corr.1, para. 48.\n65 Universal Declaration of Human Rights, arts. 2, 23 and 26; International Covenant on Economic,\nSocial and Cultural Rights, arts. 2, 6 and 13; and Convention on the Rights of the Child, arts. 2 and\n28.\n66 A/HRC/52/68 and A/HRC/52/68/Corr.1, para. 38; see also\nhttps://www.ilo.org/wcmsp5/groups/public/---ed_norm/---\nrelconf/documents/meetingdocument/wcms_872248.pdf.\n67 E/C.12/BLR/CO/7, paras. 23, 24, 41 and 42; see also https://www.salidarnast.info/post/mass-\ndismissals-for-political-reasons-in-belarus; https://www.rferl.org/a/belarus-historical-archive-\nemployees-detained/32551079.html; https://charter97.org/en/news/2021/11/29/445843/; and\nhttps://news.zerkalo.io/life/10026.html?tg; https://zbsunion.by/en/news/pressure_on_students.\n68 Labour Code of Belarus, art. 42; and Education Code of Belarus, art. 68.\n.\nOctober 2022, 72 specified that licences for professions that require one, such as legal,\nmedical, veterinary, communication, transportation, education and trade, 73 can be refused or\nrevoked for those on the list, raising concerns regarding arbitrary and/or discriminatory\ndeprivation of the right to work and to livelihood.74"},{"id":"a-hrc-55-61-p0046","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"46","seq":49,"section":"I. Right to work and education","text":"Regarding primary and secondary education, the Law on Licencing required all\neducational facilities to obtain State accreditation. In 2021, the Minister of Education, Igor\nKarpenko, explained the motivation behind the licencing of private schools, including those\nteaching in minority languages, stating that “semi-legal private kindergartens and schools\nunder the guise of individual entrepreneurs, public or religious associations were mostly used\nfor political purposes and became strongholds for the colour revolution”.75 Restricting free\nchoice of education,76 only five private schools were able to obtain the accreditation in 2023\ncompared to 35 in 2022. 77 Furthermore, following the 2022 amendments to the Code of\nEducation,78 public schools no longer provided teaching in minority languages. One of the\ntwo public schools teaching in Lithuanian was closed and the language of instruction was\nchanged to Russian in the other; there are only two public schools serving the Polish minority.\nIt is apparent that the linguistic and cultural rights of those minorities are restricted. 79"},{"id":"a-hrc-55-61-p0047","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"47","seq":50,"section":"J. Forced exile and right to nationality","text":"Based on recent information,80 OHCHR estimates that up to 300,000 individuals have\nbeen forced to leave Belarus since 2020 in what has been a concerted campaign of violence\nand repression intentionally directed at those opposing, or perceived to be opposing, the\nGovernment or expressing critical or independent voices.81 Well-founded fears of arbitrary\narrest, detention and conviction without respect for procedural safeguards and fair trial rights,\npossible torture and ill-treatment, threats of removal of children and discriminatory\nrestrictions on the right to work and education have driven men and women alike into exile.\nLGBTQ persons in Belarus reported having left the country fearing persecution, as a result,\ninter alia, of homophobic hate speech from government officials at the highest levels, the\nassociation of LGBTQ persons with the opposition movement82 and cases of public outing.83"},{"id":"a-hrc-55-61-p0048","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"48","seq":51,"section":"J. Forced exile and right to nationality","text":"Repression has been extended beyond the borders of Belarus. Belarusian authorities\nhave taken significant steps to restrict the right to nationality on discriminatory and politically\nmotivated grounds. Since July 2023, the Law on Citizenship allows authorities to revoke the\ncitizenship of individuals residing abroad who have been convicted, including in absentia, of\nextremism or for causing serious harm to the interests of Belarus.84 As at 31 December 2023,\nOHCHR is not aware of any cases of implementation of the law. The authorities did,\nhowever, begin implementing 2022 legislation allowing for trials in absentia. 85 As at\n31 December 2023, seven verdicts had been issued in absentia on political grounds against\n21 individuals, including the leaders of the political opposition. The President of Belarus\nreportedly stated there was a “need to take decisions on those who, having gone abroad, act\nto the detriment of the state …” and questioned “Do these people deserve to remain citizens\nof Belarus …?”.86 The Minister of Internal Affairs, for his part, reportedly stated “in the\nfuture, an extremist who has lost Belarus’ citizenship might be banned from entering the\ncountry for up to 30 years”.87"},{"id":"a-hrc-55-61-p0049","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"49","seq":52,"section":"J. Forced exile and right to nationality","text":"Additionally, Belarusians abroad are now required to inform the authorities if they\nobtain a residence permit or other document granting them benefits from their host State in\nconnection with political or religious views or ethnicity,88 leading to heightened surveillance\nof those in exile and their families remaining in Belarus. Further, Presidential decree No. 278\nadopted in September 2023 prevents the issuance and renewal of passports and other official\ndocuments abroad and stipulates that certain property transactions can no longer be carried\nout from abroad.89 Returning to Belarus places individuals at risk of violence and repression."},{"id":"a-hrc-55-61-p0050","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"50","seq":53,"section":"IV. Conclusions under applicable international law","text":"Human rights violations described herein further substantiate the scale and pattern of\nthe violations identified in previous reports. In the light of all available information, OHCHR\nhas reasonable grounds to believe that numerous violations of international human rights law\ncontinued to be committed in Belarus between 1 May 2020 and 31 December 2023. Such\nviolations included arbitrary deprivation of the right to life; arbitrary detention; enforced\ndisappearance; torture and other cruel, inhuman or degrading treatment or punishment,\nincluding sexual and gender-based violence; denial of the rights to due process and a fair\ntrial; unlawful interference with family life and failure to safeguard the best interests of the\nchild; violations of the right to education and work; arbitrary denial of the right to enter one’s\nown country; and violations of the rights to freedom of expression, peaceful assembly and\nassociation and of the prohibition of discrimination, notably on grounds of real or perceived\npolitical opinion."},{"id":"a-hrc-55-61-p0051","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"51","seq":54,"section":"IV. Conclusions under applicable international law","text":"In terms of additional implications under international criminal law, OHCHR noted\nin its first report on the situation in Belarus under this mandate that “[g]iven the scale and\npatterns of the violations identified in the present report, their widespread and systematic\nnature, and the evidence of official policy, knowledge and direction in respect of their\ncollective execution by multiple State organs, in particular regarding mass arbitrary detention\nin the period from 9 to 14 August 2020, there are sufficient indicia to warrant further\nassessment of the available evidence from the perspective of applicable international criminal\nlaw”. 90 In its second report, OHCHR further considered that “[s]ome of the violations\n[described in that report] may also amount to crimes against humanity, as defined in\ninternational customary law, when such acts are committed as part of a widespread or\nsystematic attack directed against any civilian population, with knowledge of the attack.\nConsidered cumulatively, the organized nature of the violations renders it improbable that\nthey were random and accidental. On the contrary, they appear to have been part of a\ncampaign of violence and repression, intentionally directed at those who were – or were\nperceived to be – opposing the Government or expressing critical or independent voices\n…”. 91 Evidence gathered during the current reporting period aligns with and strengthens\nthose views, with the campaign of repression against real or perceived political opponents\ncontinuing throughout 2023 and the Government of Belarus warning, in dehumanizing terms,\nthat the authorities would react harshly to any attempts to repeat the events of 2020. 92"},{"id":"a-hrc-55-61-p0052","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"52","seq":55,"section":"IV. Conclusions under applicable international law","text":"Assessing the cumulative body of evidence collected over the three years of the\npresent mandate, OHCHR has reasonable grounds to conclude that the Government has\nimplemented an organized, continuing and systematic campaign of violence, repression and\npunishment, pursuant to or in furtherance of a policy to attack a civilian population,\nspecifically defined and delineated by its real or perceived opposition to the Government, for\nthe purpose of silencing, suppressing, discouraging and deterring such opposition or further\nmanifestations of opposition, whether in the public space or privately. Under international\ncriminal law, persecution is the intentional and severe deprivation of fundamental rights\ncontrary to international law by reason of the identity of the group or collectivity. Taking into\naccount (a) the range of human rights violations committed against real or perceived political\nopponents in discriminatory fashion as laid out in the present report, (b) the nature and\nseverity of such violations in terms of the rights to life, physical integrity and security and to\nfreedom from arbitrary detention, as well as of the enjoyment of other fundamental freedoms,\nand (c) the systematic commission of such violations through the legal and institutional\napparatus of the State, as encouraged at highest levels, OHCHR has reasonable grounds to\nbelieve that the crime of persecution, which is a crime against humanity, may have been\ncommitted, along with other underlying acts, which may be established as a result of the\nhuman rights violations described."},{"id":"a-hrc-55-61-p0053","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"53","seq":56,"section":"V. Accountability","text":"There is no reasonable expectation that justice will be delivered for the human rights\nviolations committed in Belarus. There continues to be an active policy to shield perpetrators\nand prevent accountability. 93 OHCHR is not aware of any positive measures taken by\nBelarusian authorities to effectively investigate reported violations or to hold those\nresponsible to account. Allegations of torture or other ill-treatment have been ignored,\nincluding by judges, even when presented with credible evidence. Several victims were\npressured to not complain or reported reprisals from complaining. 94"},{"id":"a-hrc-55-61-p0054","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"54","seq":57,"section":"V. Accountability","text":"OHCHR continued to collect and preserve information and evidence regarding\nindividuals alleged to have been involved in the perpetration of the above-mentioned gross\nhuman rights violations and possible crimes under international law. This includes senior\npolitical officials and others at command levels, as well as other officials who have given\neffect to the legal regime directed against real or perceived political opponents. The extent of\nindividual criminal responsibility merits further investigation and determination by\ncompetent judicial authorities, applying international standards."},{"id":"a-hrc-55-61-p0055","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"55","seq":58,"section":"VI. Recommendations","text":"OHCHR reiterates all recommendations contained in its previous reports on\nBelarus.95"},{"id":"a-hrc-55-61-p0056","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"56","seq":59,"section":"VI. Recommendations","text":"In particular, regretting the non-implementation of                      its   previous\nrecommendations to date, OHCHR urges the Government of Belarus:\n(a)    To immediately release all individuals arbitrarily detained and sentenced\non discriminatory grounds of real or perceived political opinion, ensuring the right to\neffective remedies and adequate reparation, cease all other ongoing violations of human\nrights identified in the present report, including the systematic repression of civil society\norganizations, independent media and opposition groups and individuals, and refrain\nfrom committing such violations in the future;\n(b)   To cease the application of and to dismantle the legal regime applied to\nrepress, on discriminatory basis, the rights and freedoms of persons in Belarus and issue\nclear, comprehensive and binding instructions to law enforcement authorities and other\nrelevant institutions of Government to refrain and desist from arbitrary and\ndiscriminatory application of generally applicable law, in particular the criminal law;\n(c)    To promptly initiate independent, impartial, effective and transparent\ninvestigations into all past violations of human rights, in particular those that may\namount to crimes under international law, including the gender dimensions thereof,\nand ensure that investigations address the full chain of command relevant to individual\ncriminal responsibility."},{"id":"a-hrc-55-61-p0057","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"57","seq":60,"section":"VI. Recommendations","text":"OHCHR further recommends that the Government of Belarus:\n(a)    Immediately end incommunicado detention of individuals in its custody;\n(b)   Immediately release all children held on political grounds, expunge their\ncriminal records and establish a comprehensive system of child justice, as\nrecommended by the Committee on the Rights of the Child;96\n(c)    Ensure that counter-terrorism and counter-extremism legislation and\nrelated practices are in compliance with international norms and standards and are not\nused to silence dissent;\n(d)   Ensure non-discrimination on political or any other grounds in access to\nwork and education;\n(e)    Guarantee the right to nationality without discrimination and ensure that\nno Belarusian citizen becomes stateless, including by repealing the amendments to the\nLaw on Citizenship adopted in December 2022 and, in any event, refraining from their\nimplementation."},{"id":"a-hrc-55-61-p0058","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"58","seq":61,"section":"VI. Recommendations","text":"OHCHR continues to recommend that the States Members of the United\nNations:\n(a)     Work towards accountability through national proceedings based on\naccepted principles of extraterritorial and universal jurisdiction, as well as through\nother possible avenues, and, in combination, explore further appropriate measures\nagainst credibly alleged perpetrators of grave human rights violations, consistent with\ninternational law;\n(b)    Facilitate international refugee protection, as needed, in the light of the\ncontinuing grave, widespread and systematic human rights violations in Belarus, and\nprovide additional protection measures, where necessary, to victims, witnesses and\nother persons who have had to leave the country or were expelled, including through\nfacilitating the issuance and recognition of travel and identity documents."},{"id":"a-hrc-55-61-p0001-a1","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"1","seq":62,"section":"Annex I","text":"The Office of the United Nations High Commissioner for Human Rights (OHCHR)\npresents its compliments to the Permanent Mission of the Republic of Belarus to the United\nNations Office and other international organizations in Geneva and has the honour to refer to\nresolution 52/29 on the “Situation of human rights in Belarus in the run-up to the 2020\npresidential election and in its aftermath”, adopted by the Human Rights Council on 4 April\n2023.","annex":1},{"id":"a-hrc-55-61-p0002-a1","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"2","seq":63,"section":"Annex I","text":"The above-mentioned resolution, inter alia, requests the High Commissioner to\ncontinue “to monitor and report on the situation of human rights, to carry out a comprehensive\nexamination of all alleged human rights violations committed in Belarus since 1 May 2020\nin the run-up to the 2020 presidential election and in its aftermath, … [and] to engage with\nthe Belarusian authorities and all stakeholders”.","annex":1},{"id":"a-hrc-55-61-p0003-a1","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"3","seq":64,"section":"Annex I","text":"In fulfilment of this mandate, OHCHR wishes to inform the Permanent Mission of its\nintention to deploy a team of human rights officers to the Republic of Belarus to meet with\nauthorities, representatives of civil society organizations and relevant stakeholders, and to\ninvestigate alleged human rights violations. OHCHR stands ready to discuss with the\nPermanent Mission of the Republic of Belarus relevant practical arrangements and details for\nthe mission.","annex":1},{"id":"a-hrc-55-61-p0004-a1","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"4","seq":65,"section":"Annex I","text":"Additionally, OHCHR would like to invite the Permanent Mission of the Republic of\nBelarus to submit relevant information or documentation related to this mandate by\n1 November 2023, at the latest.","annex":1},{"id":"a-hrc-55-61-p0005-a1","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"5","seq":66,"section":"Annex I","text":"The Office of the United Nations High Commissioner for Human Rights avails itself\nof the opportunity to renew to the Permanent Mission of the Republic of Belarus to the United\nNations Office and other international organizations in Geneva the assurances of its highest\nconsideration.","annex":1},{"id":"a-hrc-55-61-p0001-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"1","seq":67,"section":"Annex II","text":"The Office of the United Nations High Commissioner for Human Rights (OHCHR)\nrespectfully requests the Government to address the queries detailed herein. OHCHR will\ntake into account the response of the Government when drafting the next report to the Human\nRights Council and may provide a link to the present note verbale and to the response of the\nGovernment in a footnote appearing on the first page of the report, unless the Government\nexplicitly requests any part of the response to remain confidential.","annex":2},{"id":"a-hrc-55-61-p0002-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"2","seq":68,"section":"Annex II","text":"OHCHR would be grateful to receive replies and any other submissions that the\nGovernment may wish to present, no later than 24 November 2023.","annex":2},{"id":"a-hrc-55-61-p0003-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"3","seq":69,"section":"Annex II","text":"OHCHR avails itself of the opportunity to renew to the Permanent Mission of the\nRepublic of Belarus to the United Nations Office and other international organizations in\nGeneva the assurances of its highest consideration.","annex":2},{"id":"a-hrc-55-61-p0004-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"4","seq":70,"section":"A. Policies and procedures","text":"Please provide details on the procedure for approving a “mass event”, and on the\nnumber of approved or rejected requests to hold such a “mass event” since the\n2021 amendments to the Law on Mass Events came into force and on the grounds for\nrejecting such requests, if any.","annex":2},{"id":"a-hrc-55-61-p0005-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"5","seq":71,"section":"A. Policies and procedures","text":"Please clarify if there is a specified procedure for handling persons who are detained\nand charged on extremism- or terrorism-related charges, while they are in detention or\nserving a sentence of imprisonment.","annex":2},{"id":"a-hrc-55-61-p0006-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"6","seq":72,"section":"A. Policies and procedures","text":"Please provide the regulations and/or rules governing the administration of places of\ndeprivation of liberty, including the procedures governing the transfer of detainees and\ndisciplinary measures.","annex":2},{"id":"a-hrc-55-61-p0007-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"7","seq":73,"section":"A. Policies and procedures","text":"Please provide details on the practice of strip search while in detention, including the\ngrounds for conducting such searches.","annex":2},{"id":"a-hrc-55-61-p0008-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"8","seq":74,"section":"A. Policies and procedures","text":"Please outline what rules of engagement on the use of force by law enforcement\nofficials applied during the 2020 protests and thereafter, in relation to crowd control\noperations.","annex":2},{"id":"a-hrc-55-61-p0009-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"9","seq":75,"section":"A. Policies and procedures","text":"Please outline the legal grounds for involving military personnel in crowd control\noperations during the protests in 2020.","annex":2},{"id":"a-hrc-55-61-p0010-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"10","seq":76,"section":"A. Policies and procedures","text":"Please share the standard operating procedures of the Belarus police or other security\nforces for the conduct of arrest and search operations, including the search of private\nresidence.","annex":2},{"id":"a-hrc-55-61-p0011-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"11","seq":77,"section":"A. Policies and procedures","text":"Please provide details on the mechanisms in place to ensure that disclosure of\nindividuals’ private information to security agencies under the Law on Medical Care and the\nLaw on Psychological Assistance does not unnecessarily and disproportionately breach the\nrights to privacy and access to health.","annex":2},{"id":"a-hrc-55-61-p0012-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"12","seq":78,"section":"A. Policies and procedures","text":"Please provide details on the mechanisms in place to ensure that disclosure of\nindividuals’ private information to security agencies under Presidential Decree 368 does not\nunnecessarily and disproportionately breach the rights to privacy and to freedom of\nexpression.","annex":2},{"id":"a-hrc-55-61-p0013-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"13","seq":79,"section":"B. Right to life","text":"Please provide a list of persons who died in the custody of Belarus authorities or as a\nresult of the use of force by Belarus security forces since 1 May 2020.","annex":2},{"id":"a-hrc-55-61-p0014-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"14","seq":80,"section":"B. Right to life","text":"Please provide detail on the steps taken to investigate the cause of death, and the\noutcome of investigation, of any person who died in the custody of Belarus authorities or as\na result of the use of force by Belarus security forces since 1 May 2020.","annex":2},{"id":"a-hrc-55-61-p0015-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"15","seq":81,"section":"C. Investigations and criminal proceedings","text":"Please provide an update on the number of persons, disaggregated by gender and age,\ninvestigated and prosecuted under extremism- and terrorism-related offences since\nMay 2021, disaggregated by the relevant offence.","annex":2},{"id":"a-hrc-55-61-p0016-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"16","seq":82,"section":"C. Investigations and criminal proceedings","text":"Please provide an update on the number of persons, disaggregated by gender and age,\narrested and prosecuted under Art. 24.23 of the Code of Administrative Offences for\nparticipation in unauthorized mass events since May 2020.","annex":2},{"id":"a-hrc-55-61-p0017-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"17","seq":83,"section":"C. Investigations and criminal proceedings","text":"Please provide information on the number of persons, disaggregated by gender and\nage, investigated and prosecuted in 2022 and 2023 under Article 193-1 of the Criminal Code\n(participation in the activities of non-registered, suspended or liquidated association).","annex":2},{"id":"a-hrc-55-61-p0018-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"18","seq":84,"section":"C. Investigations and criminal proceedings","text":"Please provide details on the number of persons, disaggregated by gender and age,\ncharged and prosecuted since May 2020 for insulting the President, a judge or representative\nof the authorities, as well as on the criminal or administrative sanction imposed.","annex":2},{"id":"a-hrc-55-61-p0019-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"19","seq":85,"section":"C. Investigations and criminal proceedings","text":"Please provide an update on the total number of “special criminal proceedings” (in\nabsentia) conducted under Chapter 49 of the Criminal Procedural Code since July 2022.","annex":2},{"id":"a-hrc-55-61-p0020-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"20","seq":86,"section":"C. Investigations and criminal proceedings","text":"Please provide information on the number of persons, disaggregated by gender and\nage, charged and prosecuted under article 411 of the Criminal Code (for disobedience to the\nadministration of the penal facilities).","annex":2},{"id":"a-hrc-55-61-p0021-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"21","seq":87,"section":"D. Freedom of expression and association","text":"Please provide an update on the total number of civil society, non-governmental\norganizations and trade unions registered in Belarus since May 2020.","annex":2},{"id":"a-hrc-55-61-p0022-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"22","seq":88,"section":"D. Freedom of expression and association","text":"Please provide the complete list of civil society, non-governmental organizations and\ntrade unions closed down by the Belarus authorities since May 2020, including details on the\nbasis for closure.","annex":2},{"id":"a-hrc-55-61-p0023-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"23","seq":89,"section":"D. Freedom of expression and association","text":"Please provide the complete list of media outlets and telegram channels that have been\nincluded in the Republican lists of extremist materials or extremist formations since\nMay 2020, including the reason for their inclusion on the list.","annex":2},{"id":"a-hrc-55-61-p0024-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"24","seq":90,"section":"D. Freedom of expression and association","text":"Please provide the complete list of websites blocked, pursuant to decisions of the\nBelarus authorities since May 2020, including the reason for their closure.","annex":2},{"id":"a-hrc-55-61-p0025-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"25","seq":91,"section":"D. Freedom of expression and association","text":"Please provide the complete list of individuals, disaggregated by gender and age, as\nwell as organisations or entities included in the Government’s “List of Belarusian citizens,\nforeign citizens or stateless persons involved in extremist activities”; “List of Organizations,\nFormations, Individual Entrepreneurs involved in Extremist Activities” and “List of\nOrganizations and Individuals involved in Terrorist Activities” and the reason for their\ninclusion.","annex":2},{"id":"a-hrc-55-61-p0026-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"26","seq":92,"section":"D. Freedom of expression and association","text":"Please provide a complete list of political parties that sought re-registration pursuant\nto the Law on the Activities of Political Parties, adopted in February 2023, and the outcome\nof the re-registration process, including the reason for rejection of re-registration, if any.","annex":2},{"id":"a-hrc-55-61-p0027-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"27","seq":93,"section":"D. Freedom of expression and association","text":"Please outline the steps taken by the Government to ensure free and fair conduct of\nthe Parliamentary election foreseen for February 2024.","annex":2},{"id":"a-hrc-55-61-p0028-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"28","seq":94,"section":"E. Due process and the right to a fair trial","text":"Please provide details on how the right to counsel is guaranteed in proceedings under\nthe Code of Administrative Offenses, as well as in disciplinary proceedings against persons\nin custody.","annex":2},{"id":"a-hrc-55-61-p0029-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"29","seq":95,"section":"E. Due process and the right to a fair trial","text":"Please provide details on the access to lawyers of those detained and charged, in\nparticular those held in solitary confinement or isolation.","annex":2},{"id":"a-hrc-55-61-p0030-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"30","seq":96,"section":"E. Due process and the right to a fair trial","text":"Please provide updated information on the number of lawyers, disaggregated by\ngender, disbarred since May 2020 and the grounds for their disbarment.","annex":2},{"id":"a-hrc-55-61-p0031-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"31","seq":97,"section":"F. Citizenship","text":"Please provide details on the number of cases, disaggregated by gender and age, of\nrevocation of citizenship by the Belarus authorities, if any, including on the grounds for\nrevoking citizenship since May 2020.","annex":2},{"id":"a-hrc-55-61-p0032-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"32","seq":98,"section":"F. Citizenship","text":"Please provide information on the steps taken to ensure that the implementation of the\nJuly 2023 amendment to the Law on Citizenship does not result in statelessness, including of\nchildren born to Belarusian citizens currently living abroad.","annex":2},{"id":"a-hrc-55-61-p0033-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"33","seq":99,"section":"G. Economic, social and cultural rights","text":"Please provide information on the number of persons dismissed from\nState-employment on grounds of having participated in peaceful protest or otherwise\nexercising their freedom of expression or opinion, association or assembly and/or for being\nabsent from work without the ability to provide a valid justification.","annex":2},{"id":"a-hrc-55-61-p0034-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"34","seq":100,"section":"G. Economic, social and cultural rights","text":"Please provide information on the number of persons expelled from educational\ninstitutions on grounds of having participated in peaceful protest or otherwise exercising their\nfreedom of expression or opinion, association or assembly and/or for being absent without\nthe ability to provide a valid justification.","annex":2},{"id":"a-hrc-55-61-p0035-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"35","seq":101,"section":"G. Economic, social and cultural rights","text":"Please provide information on the number of private educational and cultural\ninstitutions closed since 1 May 2020.","annex":2},{"id":"a-hrc-55-61-p0036-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"36","seq":102,"section":"G. Economic, social and cultural rights","text":"Please provide information on the number of schools where language of instruction\nwas changed from a national minority language to Russian since 1 May 2020.","annex":2},{"id":"a-hrc-55-61-p0037-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"37","seq":103,"section":"G. Economic, social and cultural rights","text":"Please provide information about the practice of appointing a person in charge of\nsecurity issues at the educational and other public institutions and state-owned companies as\nof September 2020, the number of such positions introduced, and the rule or regulation which\nregulates this practice.","annex":2},{"id":"a-hrc-55-61-p0038-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"38","seq":104,"section":"H. Accountability for alleged violations of human rights","text":"Please provide information on the number of complaints received since May 2020\ninto human rights violations, allegedly committed by law enforcement personnel, detail on\nthe steps taken to investigate them and the outcome of those investigations.","annex":2},{"id":"a-hrc-55-61-p0039-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"39","seq":105,"section":"H. Accountability for alleged violations of human rights","text":"Please provide details of remedies provided to victims of human rights violations\nsince May 2020, if any, including reparations.","annex":2},{"id":"a-hrc-55-61-p0040-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"40","seq":106,"section":"H. Accountability for alleged violations of human rights","text":"Please outline action taken against perpetrators of human rights violations since\nMay 2020, including prosecutions and convictions, if any.","annex":2},{"id":"a-hrc-55-61-p0041-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"41","seq":107,"section":"I. Implementation of previous recommendations","text":"Please outline any steps taken to implement recommendations contained in the last\nthree OHCHR reports on Belarus (A/HRC/52/68, A/HRC/49/71 and A/HRC/46/4).","annex":2},{"id":"a-hrc-55-61-p0042-a2","rec_id":"recBsBtAmsSlwegkE","symbol":"A/HRC/55/61","n":"42","seq":108,"section":"J. Access","text":"Please reply to the High Commissioner’s note verbale dated 22 June 2023 requesting\naccess to Belarus and grant such access.","annex":2}]});